<!DOCTYPE html>
<html lang="zh-CN">
  <head>

        <!-- [新增] 动态立绘渲染引擎 (专属烙印版) -->
<script>
(function () {
  console.log("✨ [立绘引擎] 启动：多角色匹配模式");

  const MAX_ATTEMPTS = 6;
  const SCAN_INTERVAL = 1200;
  const QUERY_SELECTOR = "div, li, section";
  let attemptCount = 0;
  let scanTimer = null;

  function getPortraitMap() {
    const map = window.PORTRAIT_MAP;
    if (!map || typeof map !== "object" || Object.keys(map).length === 0) {
      console.log("⚠️ [立绘引擎] PORTRAIT_MAP 未就绪或为空，等待下一轮...");
      return {};
    }
    return map;
  }

function buildPortraitHTML(roleName, portraitUrl) {
  const isMobile = /Mobi|Android|iPhone|iPad|iPod|Windows Phone/i.test(navigator.userAgent);

  // 移动端：左右满幅 + 降低高度，避免“过长”
  const wrapWidth = isMobile ? "calc(100%)" : "100%";
  const wrapMarginX = isMobile ? "-2px" : "0";
  const wrapHeight = isMobile ? "24vh" : "40vh";
  const wrapMinHeight = isMobile ? "140px" : "240px";
  const wrapMaxHeight = isMobile ? "300px" : "7000px";
  const imgPos = isMobile ? "center top" : "top";

  return `
    <div data-pt-wrapper="1" style="
      position: relative;
      width: ${wrapWidth};
      margin-left: ${wrapMarginX};
      margin-right: ${wrapMarginX};
      height: ${wrapHeight};
      min-height: ${wrapMinHeight};
      max-height: ${wrapMaxHeight};
      overflow: hidden;
      -webkit-mask-image: linear-gradient(to bottom, black 68%, transparent 100%);
      mask-image: linear-gradient(to bottom, black 68%, transparent 100%);
    ">
      <img src="${portraitUrl}" alt="${roleName}" style="
        width: 100%;
        height: 100%;
        object-fit: cover;
        object-position: ${imgPos};
        display: block;
      ">
    </div>
  `;
}

  function matchPortraitUrl(rawTag, map) {
    const clean = rawTag.replace(/\s+/g, '');
    if (map[clean]) return { name: clean, url: map[clean] };
    if (map[rawTag]) return { name: rawTag, url: map[rawTag] };
    const matchedKey = Object.keys(map).find((k) => k === clean || clean.includes(k) || k.includes(clean));
    if (matchedKey) return { name: matchedKey, url: map[matchedKey] };
    return null;
  }

  function scanAllRoles() {
    attemptCount++;
    const map = getPortraitMap();
    const entries = Object.entries(map);

    console.log(`🧭 [立绘引擎] 第 ${attemptCount}/${MAX_ATTEMPTS} 轮扫描 (单次DOM遍历模式)`);

    if (!entries.length) {
      if (attemptCount < MAX_ATTEMPTS) scheduleNextScan();
      return;
    }

    const bodyText = document.body ? (document.body.innerText || document.body.textContent || "") : "";
    if (!bodyText.includes("【立绘") && !bodyText.includes("【 立绘")) {
      if (attemptCount < MAX_ATTEMPTS) {
        scheduleNextScan();
      } else {
        console.log("🛌 [立绘引擎] 达到最大轮次，停止扫描。");
      }
      return;
    }

    const allElements = document.querySelectorAll(QUERY_SELECTOR);
    const tagRegex = /【\s*立绘\s*([^】]+)\s*】/g;
    let replacedCount = 0;

    allElements.forEach((el) => {
      if (el.getAttribute("data-pt-role") || el.querySelector('[data-pt-wrapper="1"]')) return;

      const txt = el.textContent || "";
      if (!txt.includes("【立绘") && !txt.includes("【 立绘")) return;

      const hasMatchingChild = Array.from(el.children).some((child) => {
        const cTxt = child.textContent || "";
        return cTxt.includes("【立绘") || cTxt.includes("【 立绘");
      });
      if (hasMatchingChild) return;

      let match;
      tagRegex.lastIndex = 0;
      while ((match = tagRegex.exec(txt)) !== null) {
        const rawRole = match[1].trim();
        const found = matchPortraitUrl(rawRole, map);
        if (found) {
          console.log(`✅ [立绘引擎] 锁定并渲染角色：${found.name}（原始标签：${rawRole}）`, el);
          el.setAttribute("data-pt-role", found.name);

          Array.from(el.children).forEach((child) => {
            if (child.tagName !== "SCRIPT" && child.tagName !== "STYLE") {
              child.style.display = "none";
            }
          });

          Array.from(el.childNodes).forEach((node) => {
            if (node.nodeType === 3) node.textContent = "";
          });

          el.style.cssText +=
            "padding:0 !important;border:none !important;background:transparent !important;box-shadow:none !important;display:block !important;overflow:hidden !important;";

          const holder = document.createElement("div");
          holder.innerHTML = buildPortraitHTML(found.name, found.url);
          el.appendChild(holder.firstElementChild);

          replacedCount++;
          break;
        }
      }
    });

    console.log(`📊 [立绘引擎] 本轮结果：匹配并替换 ${replacedCount} 处立绘`);

    if (attemptCount < MAX_ATTEMPTS) {
      scheduleNextScan();
    } else {
      console.log("🛌 [立绘引擎] 达到最大轮次，停止扫描。");
    }
  }

  function scheduleNextScan() {
    clearTimeout(scanTimer);
    scanTimer = setTimeout(scanAllRoles, SCAN_INTERVAL);
  }

  const observer = new MutationObserver(() => {
    if (attemptCount >= MAX_ATTEMPTS) return;
    console.log("♻️ [立绘引擎] DOM 发生变化，重新排队扫描");
    scheduleNextScan();
  });

  function startEngine() {
    observer.observe(document.body, { childList: true, subtree: true, characterData: true });
    scheduleNextScan();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", startEngine);
  } else {
    startEngine();
  }

  // 暴露给卡片复用：修复 ReferenceError（截图所示）
  window.buildPortraitHTML = buildPortraitHTML;
  window.openPortraitLightbox = function (url, title) {
    const modal = document.getElementById('pc-portrait-lightbox');
    const img = document.getElementById('pc-lightbox-img');
    const cap = document.getElementById('pc-lightbox-cap');
    if (!modal || !img) return;
    let src = url;
    try { src = encodeURI(decodeURI(url)); } catch(e) { try { src = encodeURI(url); } catch(e2) {} }
    img.src = src;
    img.alt = title || '';
    if (cap) cap.textContent = title ? `${title} - 立绘原图` : '';
    modal.classList.add('active');
  };
})();
</script>




