        /* PC 带立绘卡片 — 方案1 紧凑左右分栏 (145px 立绘 + 自适应属性) */
        .pc-portrait-layout {
          display: flex;
          flex-direction: column;
          gap: 0.5rem;
        }
        .pc-portrait-box {
          width: 100%;
          border-radius: 8px;
          overflow: hidden;
          border: 1.5px solid #dfd2c0;
          box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
          cursor: pointer;
          background: #2a201c;
          position: relative;
          height: 200px;
          flex-shrink: 0;
        }
        .pc-portrait-box img {
          width: 100%;
          height: 100%;
          object-fit: cover;
          object-position: center top;
          display: block;
          transition: transform 0.35s ease;
        }
        .pc-portrait-box:hover img {
          transform: scale(1.06);
        }
        .pc-portrait-mask {
          position: absolute;
          inset: 0;
          background: linear-gradient(to top, rgba(0,0,0,0.55) 0%, transparent 40%);
          pointer-events: none;
        }
        .pc-portrait-content {
          flex: 1;
          min-width: 0;
        }
        @media (min-width: 480px) {
          .pc-portrait-layout {
            flex-direction: row;
            gap: 0.65rem;
            align-items: stretch;
          }
          .pc-portrait-layout:has(.pc-portrait-box[style*="display: none"]) {
            display: block;
          }
          .pc-portrait-box {
            width: 145px;
            min-width: 145px;
            max-width: 145px;
            height: 200px;
            align-self: flex-start;
            border-width: 2px;
          }
        }
