        /* --- 多场景 RPG 战术地图通用样式 --- */
        .tactical-map-container { 
            position: relative; width: 100%; height: 350px; 
            background-color: #181425; 
            border: 4px solid #3a4466; border-radius: 8px; 
            overflow: hidden; 
            box-shadow: 0 8px 0 rgba(0,0,0,0.2), inset 0 4px 20px rgba(0,0,0,0.5); 
            margin-top: 0.5rem; cursor: crosshair; user-select: none; 
            font-family: 'Courier New', Courier, monospace; 
            touch-action: none; /* [新增] 禁用浏览器的默认触摸动作，专心处理地图拖拽 */
        }

        /* 根据环境动态变换 UI 色调 */
        .tactical-map-container.env-bright-room { background-color: #e8cfa6; border-color: #a37855; }
        .tactical-map-container.env-street { background-color: #d1d5db; border-color: #6b7280; }
        .tactical-map-container.env-mall { background-color: #e2e8f0; border-color: #94a3b8; }
        .tactical-map-container.env-wilderness { background-color: #274b33; border-color: #183320; }
        .tactical-map-container.env-cave { background-color: #111118; border-color: #2d2b38; }
        .tactical-map-container.env-seaside { background-color: #f8f5ee; border-color: #e5e7eb; }
        .tactical-map-container.env-snowfield { background-color: #f0f9ff; border-color: #bae6fd; }
        .tactical-map-container.env-restaurant { background-color: #2c1e16; border-color: #5c4033; }
        .tactical-map-container.env-desert { background-color: #fef3c7; border-color: #d97706; }
        .tactical-map-container.env-volcano { background-color: #111827; border-color: #991b1b; }
        .tactical-map-container.env-nightmarket { background-color: #1e1b4b; border-color: #4338ca; }
        .tactical-map-container.env-hospital { background-color: #f0fdfa; border-color: #5eead4; }
        .tactical-map-container.env-restaurant { background-color: #2c1e16; border-color: #5c4033; } /* 海边主题改为治愈系暖沙色 */

        .tactical-map-container:active { cursor: grabbing; }
        .map-layer { position: absolute; inset: 0; width: 100%; height: 100%; transform-origin: 0 0; image-rendering: pixelated; }
        .map-svg-bg { width: 100%; height: 100%; pointer-events: none; transition: all 0.5s ease; }

        .map-marker { position: absolute; transform: translate(-50%, -50%); cursor: pointer; z-index: 20; }
        .map-marker:hover { z-index: 25; }
        .map-marker.active { z-index: 30; }

        /* 核心：RPG物品浮动呼吸动画 */
        .marker-emoji { 
            font-size: 1.8rem; position: relative; z-index: 2; 
            display: inline-block;
            animation: rpg-float 2s ease-in-out infinite;
            filter: drop-shadow(0px 4px 0px rgba(0,0,0,0.4)); 
        }
        .map-marker:nth-child(2n) .marker-emoji { animation-delay: 0.3s; animation-duration: 2.2s; }
        .map-marker:nth-child(3n) .marker-emoji { animation-delay: 0.7s; animation-duration: 1.8s; }

        /* 底部伪阴影 */
        .marker-shadow {
            position: absolute; bottom: -6px; left: 50%; transform: translateX(-50%);
            width: 20px; height: 8px; background: rgba(0,0,0,0.4); border-radius: 50%;
            animation: shadow-pulse 2s ease-in-out infinite;
            z-index: 1; pointer-events: none;
        }
        .map-marker:nth-child(2n) .marker-shadow { animation-delay: 0.3s; animation-duration: 2.2s; }
        .map-marker:nth-child(3n) .marker-shadow { animation-delay: 0.7s; animation-duration: 1.8s; }

        /* 选中时的光圈 */
        .marker-pulse { position: absolute; inset: -8px; border-radius: 50%; border: 3px dashed #fbbf24; transform: scale(0); transition: all 0.3s; opacity: 0; }
        .map-marker.active .marker-pulse { animation: select-spin 4s linear infinite; opacity: 1; transform: scale(1); }
        .map-marker.active .marker-emoji { filter: drop-shadow(0px 0px 8px #fbbf24); }

        /* 复古 Tooltip 适配多环境 */
        .map-tooltip { 
            position: absolute; bottom: 100%; left: 50%; transform: translateX(-50%) translateY(-10px); 
            background: rgba(30, 30, 40, 0.9); color: #fff; padding: 4px 8px; border: 2px solid #5a6988; border-radius: 0px; 
            font-size: 0.75rem; font-weight: bold; white-space: nowrap; pointer-events: none; opacity: 0; 
            transition: opacity 0.2s, transform 0.2s; box-shadow: 4px 4px 0 rgba(0,0,0,0.3);
        }
        .map-marker:hover .map-tooltip { opacity: 1; transform: translateX(-50%) translateY(-15px); }
        .env-bright-room .map-tooltip, .env-mall .map-tooltip, .env-street .map-tooltip { background: #f8fafc; color:#0f172a; border-color: #94a3b8; }
        .env-seaside .map-tooltip { background: #ffffff; color: #334155; border-color: #cbd5e1; }
        .env-snowfield .map-tooltip { background: #f8fafc; color: #0c4a6e; border-color: #7dd3fc; }
        .env-restaurant .map-tooltip { background: #1c140d; color: #fef3c7; border-color: #92400e; }
        .env-desert .map-tooltip { background: #fffbeb; color: #92400e; border-color: #f59e0b; }
        .env-volcano .map-tooltip { background: #1f2937; color: #f87171; border-color: #b91c1c; }
        .env-nightmarket .map-tooltip { background: #312e81; color: #f472b6; border-color: #6366f1; }
        .env-hospital .map-tooltip { background: #ffffff; color: #0f766e; border-color: #2dd4bf; }

        /* 复古弹窗面板 */
        .map-info-panel { 
            position: absolute; bottom: 10px; left: 10px; right: 10px; 
            background: #181425; border: 4px solid #3a4466; border-radius: 4px; padding: 6px 10px; z-index: 50; cursor: pointer; 
            transform: translateY(150%); transition: transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275); 
