      const triggerQuickReply = text => {
        if (!text || ['…', '...'].includes(text.trim()) || text.trim().length === 0) return;
        if (typeof triggerSlash === 'function') {
          triggerSlash(`/send ${text}|/trigger`);
        } else {
          console.log('SillyTavern environment not detected. Would send:', text);
        }
      };

      const sendToChatBox = text => {
        if (!text || ['…', '...'].includes(text.trim()) || text.trim().length === 0) return;

        try {
          const textarea = parent.document.getElementById('send_textarea') || parent.document.querySelector('#send_textarea');
          if (!textarea) {
            console.log('未找到聊天输入框 (#send_textarea)');
            return;
          }
          const currentContent = textarea.value || '';
          if (currentContent.includes(text.trim())) {
            console.log('聊天框中已包含该文本，跳过添加');
            return;
          }
          const separator = currentContent.trim() ? '\n' : '';
          const newContent = currentContent + separator + text.trim();
          textarea.value = newContent;
          textarea.dispatchEvent(new Event('input', { bubbles: true }));
          console.log('已添加文本到聊天框:', text.trim());
        } catch (error) {
          console.error('发送到聊天框时出错:', error);
          triggerQuickReply(text);
        }
      };

      function getBadgeCollapseThreshold() {
        const v = parseInt(localStorage.getItem('badgeCollapseThreshold'), 10);
        return Number.isFinite(v) && v >= 1 && v <= 20 ? v : 5;
      }

      function applyBadgeCollapseStyle() {
        const t = getBadgeCollapseThreshold();
        let el = document.getElementById('badge-collapse-style');
        if (!el) {
          el = document.createElement('style');
          el.id = 'badge-collapse-style';
          document.head.appendChild(el);
        }
        el.textContent = `.item-badge-container.collapsed .item-badge:nth-child(n+${t + 1}){display:none}`;
      }

      function createBadgeExpandButton(badgeContainer, totalCount) {
        const btn = document.createElement('button');
        btn.className = 'item-expand-btn';
        btn.title = '点击展开全部';
        const threshold = getBadgeCollapseThreshold();
        btn.textContent = `+${totalCount - threshold}`;
        btn.addEventListener('click', e => {
          e.stopPropagation();
          const t = getBadgeCollapseThreshold();
          const isExpanded = badgeContainer.classList.contains('expanded');
          if (isExpanded) {
            badgeContainer.classList.remove('expanded');
            badgeContainer.classList.add('collapsed');
            btn.textContent = `+${totalCount - t}`;
          } else {
            badgeContainer.classList.add('expanded');
            badgeContainer.classList.remove('collapsed');
            btn.textContent = '收起';
          }
        });
        return btn;
      }

      function refreshExistingBadgeContainers() {
        const t = getBadgeCollapseThreshold();
        document.querySelectorAll('.item-badge-container').forEach(container => {
          const wrapper = container.parentElement;
          if (!wrapper || !wrapper.classList.contains('item-badge-wrapper')) return;
          const count = container.querySelectorAll('.item-badge').length;
          let btn = wrapper.querySelector('.item-expand-btn');
          const isExpanded = container.classList.contains('expanded');
          if (count > t) {
            if (!isExpanded) container.classList.add('collapsed');
            if (!btn) {
              btn = createBadgeExpandButton(container, count);
              wrapper.appendChild(btn);
            }
            btn.textContent = isExpanded ? '收起' : `+${count - t}`;
            btn.style.display = '';
          } else {
            container.classList.remove('collapsed', 'expanded');
            if (btn) btn.style.display = 'none';
          }
        });
      }

