      function initSettingsPanel() {
        const settingsBtn = document.getElementById('settings-btn');
        const settingsClose = document.getElementById('settings-close');
        const displayModeRadios = document.querySelectorAll('input[name="display-mode"]');
        const actionModeRadios = document.querySelectorAll('input[name="action-mode"]');

        if (settingsBtn) {
          settingsBtn.addEventListener('click', () => mmsToggleSettingsView(true));
        }
        if (settingsClose) {
          settingsClose.addEventListener('click', () => mmsToggleSettingsView(false));
        }
        Object.keys(MMS_SETTING_TAB_NAMES).forEach(k => {
          const btn = document.getElementById('tab-btn-' + k);
          if (btn) btn.addEventListener('click', () => mmsSwitchSettingTab(k));
        });

        document.addEventListener('keydown', e => {
          if (e.key === 'Escape') {
            const settingsView = document.getElementById('settings-panel');
            if (settingsView && settingsView.style.display === 'block') {
              mmsToggleSettingsView(false);
            }
          }
        });

        const savedDisplayMode = localStorage.getItem('displayMode') || 'status-only';
        displayModeRadios.forEach(radio => {
          if (radio.value === savedDisplayMode) {
            radio.checked = true;
          }
          radio.addEventListener('change', () => {
            if (radio.checked) {
              updateDisplayMode(radio.value);
              localStorage.setItem('displayMode', radio.value);
            }
          });
        });

        updateDisplayMode(savedDisplayMode);

        const savedActionMode = localStorage.getItem('actionMode') || 'send-to-chat';
        actionModeRadios.forEach(radio => {
          if (radio.value === savedActionMode) {
            radio.checked = true;
          }
          radio.addEventListener('change', () => {
            if (radio.checked) {
              localStorage.setItem('actionMode', radio.value);
            }
          });
        });

        const thresholdValueEl = document.getElementById('threshold-value');
        const minusBtn = document.getElementById('threshold-minus');
        const plusBtn = document.getElementById('threshold-plus');
        const syncThresholdUI = () => {
          const t = getBadgeCollapseThreshold();
          if (thresholdValueEl) thresholdValueEl.textContent = String(t);
          if (minusBtn) minusBtn.disabled = t <= 1;
          if (plusBtn) plusBtn.disabled = t >= 20;
        };
        if (minusBtn) {
          minusBtn.addEventListener('click', () => {
            let t = getBadgeCollapseThreshold();
            t = Math.max(1, t - 1);
            localStorage.setItem('badgeCollapseThreshold', String(t));
            syncThresholdUI();
            applyBadgeCollapseStyle();
            refreshExistingBadgeContainers();
          });
        }
        if (plusBtn) {
          plusBtn.addEventListener('click', () => {
            let t = getBadgeCollapseThreshold();
            t = Math.min(20, t + 1);
            localStorage.setItem('badgeCollapseThreshold', String(t));
            syncThresholdUI();
            applyBadgeCollapseStyle();
            refreshExistingBadgeContainers();
          });
        }
        syncThresholdUI();
      }

