        getSVG() {
          const uid = this.container.id; 

          // === [新增] 底图拦截逻辑 ===
          let matchedBg = null;
          if (typeof BACKGROUND_MAP !== 'undefined') {
              // 遍历字典，如果当前场景名（this.mapTypeStr）包含了字典里的关键字，就使用该图片
              for (let key in BACKGROUND_MAP) {
                  if (this.mapTypeStr.includes(key)) {
                      matchedBg = BACKGROUND_MAP[key];
                      break;
                  }
              }
          }

          // 如果找到了匹配的底图，直接返回 <img> 标签，铺满底层
          if (matchedBg) {
              return `<img src="${matchedBg}" class="map-svg-bg" style="width: 100%; height: 100%; object-fit: cover; object-position: center;" />`;
          }

          // 如果没找到，就继续执行原来的逻辑，渲染默认的色块地图
          switch(this.envType) {
            case 'blood-ruins':
              return `
                <svg class="map-svg-bg" viewBox="0 0 1000 1000" preserveAspectRatio="xMidYMid slice">
