                  <rect width="1000" height="1000" fill="url(#abyss-bg-${uid})" />

                  <!-- 深渊中流动的暗红雾气 -->
                  <path d="M 0 300 Q 250 150 500 400 T 1000 200" fill="none" stroke="#7f1d1d" stroke-width="80" opacity="0.15" filter="blur(20px)"/>
