                  <!-- 祭坛地面的暗色几何刻痕 -->
                  <polygon points="450,150 650,220 780,450 720,700 550,800 300,720 220,500 320,250" fill="none" stroke="#27272a" stroke-width="2"/>

                  <!-- ================= 4. 撕裂祭坛的岩浆/血色裂缝 ================= -->
                  <!-- 裂缝的光晕层 -->
                  <path d="M 500 500 L 350 300 L 250 200 M 500 500 L 700 400 L 850 350 M 500 500 L 600 700 L 750 850 M 500 500 L 300 650 L 200 800 M 350 300 L 450 150 M 600 700 L 400 900" stroke="#991b1b" stroke-width="15" fill="none" filter="blur(8px)"/>
                  <!-- 裂缝的炽热层 -->
                  <path d="M 500 500 L 350 300 L 250 200 M 500 500 L 700 400 L 850 350 M 500 500 L 600 700 L 750 850 M 500 500 L 300 650 L 200 800 M 350 300 L 450 150 M 600 700 L 400 900" stroke="#dc2626" stroke-width="6" fill="none" filter="blur(2px)"/>
                  <!-- 裂缝的极高温核心 (撕裂感) -->
                  <path d="M 500 500 L 350 300 L 250 200 M 500 500 L 700 400 L 850 350 M 500 500 L 600 700 L 750 850 M 500 500 L 300 650 L 200 800 M 350 300 L 450 150 M 600 700 L 400 900" stroke="#fca5a5" stroke-width="1.5" fill="none"/>

                  <!-- ================= 5. 古老且断裂的血色阵纹 (残破的规则) ================= -->
                  <!-- 断裂的外环阵法 -->
                  <circle cx="500" cy="500" r="320" fill="none" stroke="#dc2626" stroke-width="3" stroke-dasharray="40 100 200 80 10 50" opacity="0.6"/>
                  <circle cx="500" cy="500" r="300" fill="none" stroke="#ef4444" stroke-width="1" stroke-dasharray="10 30 50 150 20 60" opacity="0.8"/>

                  <!-- 残缺的六芒星阵 -->
                  <polygon points="500,220 742,640 258,640" fill="none" stroke="#b91c1c" stroke-width="2" stroke-dasharray="100 50 200 80" opacity="0.5"/>
                  <polygon points="500,780 742,360 258,360" fill="none" stroke="#b91c1c" stroke-width="2" stroke-dasharray="150 30 50 120" opacity="0.5"/>

                  <!-- 散落在四周的微小血色符文光点 -->
