                  <circle cx="680" cy="750" r="2.5" fill="#f87171" filter="blur(1px)"/>

                  <!-- ================= 6. 核心：不灭的血色晶体 (生命力与能量的凝结) ================= -->
                  <!-- 晶体散发出的巨大能量光晕 -->
                  <circle cx="500" cy="500" r="150" fill="url(#blood-mist-${uid})" />
                  <circle cx="500" cy="500" r="80" fill="#dc2626" opacity="0.2" filter="blur(15px)"/>

                  <!-- 悬浮晶体向下的深渊投影 -->
                  <polygon points="480,620 550,700 450,700" fill="#000" opacity="0.6" filter="blur(6px)"/>

