                  <!-- 围绕晶体缓缓旋转的碎石和血光 (动态静止感) -->
                  <circle cx="430" cy="450" r="4" fill="#fca5a5" opacity="0.9"/>
                  <circle cx="570" cy="540" r="3" fill="#ef4444" opacity="0.8"/>
