extractLocationName(locationText) {
  // 移除emoji和前缀符号
  let cleaned = locationText.replace(/^[\s\-·•◦▪▸►➤→]+/, '').trim();
  // 移除emoji
  cleaned = cleaned.replace(/[\u{1F300}-\u{1F9FF}]|[\u{2600}-\u{26FF}]|[\u{2700}-\u{27BF}]|[\u{1F600}-\u{1F64F}]|[\u{1F680}-\u{1F6FF}]/gu, '').trim();
  // 移除前缀符号
  cleaned = cleaned.replace(/^[\s\-·•◦▪▸►➤→📍🏪🏥🛠️🅿️📦🌲]+/, '').trim();
  // 提取地点名（取第一个空格或破折号前的部分，或整个字符串）
  const match = cleaned.match(/^([^\-\–\—]+)/);
  if (match) {
    return match[1].trim();
  }
  return cleaned;
}

