createCharacterEntry(text, categoryKey) {
  const entry = document.createElement('div');

  // 确定条目类型
  let entryType = '';
  const lowerKey = categoryKey.toLowerCase();
  if (lowerKey.includes('盟友') || lowerKey.includes('ally') || lowerKey.includes('同伴')) {
    entryType = 'ally-entry';
  } else if (lowerKey.includes('敌人') || lowerKey.includes('enemy') || lowerKey.includes('对手')) {
    entryType = 'enemy-entry';
  } else if (lowerKey.includes('npc')) {
    entryType = 'npc-entry';
  }

  entry.className = `character-entry ${entryType}`;
  entry.style.cursor = 'pointer';  // 添加手型光标

  // 解析文本
  let remaining = text;

  // 提取开头的emoji
  const emojiMatch = remaining.match(/^([\u{1F300}-\u{1F9FF}]|[\u{2600}-\u{26FF}]|[\u{2700}-\u{27BF}]|[\u{1F600}-\u{1F64F}]|[\u{1F680}-\u{1F6FF}]|[\u{2B50}]|[\u{26A0}]|[\u{1F4AC}]|[\u{1F464}-\u{1F468}][\u{200D}]?[\u{1F469}]?[\u{200D}]?[\u{1F467}]?|👨‍👩‍👦|👱‍♀️|⚠️|🤖)\s*/u);
  let emoji = '';
  if (emojiMatch) {
    emoji = emojiMatch[1];
    remaining = remaining.slice(emojiMatch[0].length);
  }

  // 提取【】中的名字
  const nameMatch = remaining.match(/【([^】]+)】/);
  let name = '';
  if (nameMatch) {
    name = nameMatch[1];
    remaining = remaining.replace(/【[^】]+】/, '');
  }

  // 提取所有[]中的标签
  const tags = [];
  const tagRegex = /\[([^\]]+)\]/g;
  let tagMatch;
  while ((tagMatch = tagRegex.exec(remaining)) !== null) {
    tags.push(tagMatch[1]);
  }
  remaining = remaining.replace(/\[[^\]]+\]/g, '').trim();

  // 剩余的是描述
  const description = remaining.trim();

  // 添加点击事件 - 发送"接触xx"
  if (name) {
    entry.title = `点击接触: ${name}`;
    entry.addEventListener('click', (e) => {
      e.stopPropagation();
      const contactText = `接触${name}`;

      const actionMode = localStorage.getItem('actionMode') || 'send-to-chat';
      if (actionMode === 'send-to-chat') {
        sendToChatBox(contactText);
      } else {
        triggerQuickReply(contactText);
      }

      // 点击反馈效果
      const originalBg = entry.style.background;
      entry.style.background = 'rgba(157, 124, 245, 0.3)';
      setTimeout(() => {
        entry.style.background = originalBg;
      }, 300);
    });
  }

  // 构建HTML
  if (emoji) {
    const emojiSpan = document.createElement('span');
    emojiSpan.className = 'char-emoji';
    emojiSpan.textContent = emoji;
    entry.appendChild(emojiSpan);
  }

  const content = document.createElement('div');
  content.className = 'char-content';

  // 名字和标签行 - 使用 inline 布局确保不换行
  const headerLine = document.createElement('div');
  headerLine.style.whiteSpace = 'nowrap';
  headerLine.style.overflowX = 'auto';
  headerLine.style.scrollbarWidth = 'none';

  if (name) {
    const nameSpan = document.createElement('span');
    nameSpan.className = 'char-name';
    nameSpan.textContent = name;
    headerLine.appendChild(nameSpan);
  }

  tags.forEach(tag => {
    const tagSpan = document.createElement('span');
    tagSpan.className = 'char-tag';
    tagSpan.textContent = tag;
    headerLine.appendChild(tagSpan);
  });

  content.appendChild(headerLine);

  // 描述
  if (description) {
    const descSpan = document.createElement('span');
    descSpan.className = 'char-desc';
    descSpan.textContent = description;
    content.appendChild(descSpan);
  }

  entry.appendChild(content);

  return entry;
}

