      const MMS_MARKER_RE = /^(.*?)\s*【(.*?)】\s*\(\s*(\d+)\s*,\s*(\d+)\s*\)\s*(.*)$/;

      // ---------- MMS v2：名称工具 ----------

      // 轻清洗：仅去emoji与空白（用于展示、正文命中检测）
