      function mmsDetectEntryType(userData, plainName) {
        const keys = Object.keys(userData).filter((k) => !/名字|姓名|名称/.test(k));
        const hasField = (pred) => keys.some(pred);
        // 行动选项：名字含"团队行动"且有选项数组
        if (/行动/.test(plainName) && keys.some((k) => /选项/.test(k))) return 'action';
