        if (keys.length > 0 && keys.every(isMarkerArray)) return 'map';
        // 角色：有属性/穿着/内心/武器/物品等键
        if (hasField((k) => /属性|穿着|内心|武器|物品|修为|生命|灵力/.test(k))) return 'char';
        return 'custom';
      }

      function mmsNormalizeState(raw) {
        if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return null;
        const rootKey = Object.keys(raw).find((k) => k !== '行动选项') || Object.keys(raw)[0];
        if (!rootKey) return null;
        const root = raw[rootKey];
        if (!root || typeof root !== 'object' || Array.isArray(root)) return null;

        // 仅字面量「用户列表」视为旧结构；「角色列表」独立存在时按新结构透传（渲染/合并均兼容）
        const userListKey = Object.keys(root).find((k) => k === '用户列表');
        const oldList = userListKey && Array.isArray(root[userListKey]) ? root[userListKey] : null;
        if (!oldList) {
          // 已是模块化结构（或未知结构）：原样透传
          return raw;
        }

        // ---- 旧结构转换 ----
        const out = {};
        for (const k of Object.keys(root)) {
          if (k === userListKey) continue;
          out[k] = root[k]; // 日期/地点/根级行动选项/自定义键全部保留
        }

        const charList = [];
        let people = null;
        let base = null;
        let map = null;
        let action = out['行动选项'] || null;

        for (const entry of oldList) {
          if (!entry || typeof entry !== 'object') continue;
          const innerKey = Object.keys(entry).find((k) => k === '用户' || k === '角色');
          const userData = innerKey ? entry[innerKey] : entry;
          if (!userData || typeof userData !== 'object') continue;
          const nameField = mmsFindNameField(userData);
          const name = nameField ? String(userData[nameField] || '') : '';
          const plain = mmsPlainName(name);
          const type = mmsDetectEntryType(userData, plain);

          if (type === 'action') {
            const optKey = Object.keys(userData).find((k) => /选项/.test(k));
            action = {
              名字: nameField ? name : '🧑 团队行动',
              选项: optKey && Array.isArray(userData[optKey]) ? userData[optKey] : [],
            };
          } else if (type === 'people') {
            people = Object.assign({}, people || {}, userData);
            if (nameField) delete people[nameField];
          } else if (type === 'base') {
            base = Object.assign({}, base || {}, userData);
            if (nameField) delete base[nameField];
            if (base['总览']) {
              const nm = String(base['总览']).match(/\[名称[:：]\s*([^\]]+)\]/);
              const cm = String(base['总览']).match(/\[团队现金[:：]\s*([^\]]+)\]/);
              if (nm) base['名称'] = base['名称'] != null ? base['名称'] : nm[1].trim();
              if (cm) base['现金'] = base['现金'] != null ? base['现金'] : cm[1].trim();
              if (!nm && base['名称'] == null) base['名称'] = base['总览'];
              delete base['总览'];
            }
          } else if (type === 'map') {
            map = map || {};
            for (const k of Object.keys(userData)) {
              if (/名字|姓名|名称/.test(k)) continue;
              map[k] = userData[k];
            }
          } else if (type === 'char') {
            const c = Object.assign({}, userData);
            charList.push({ 角色: c });
          } else {
            // 自定义模块：名字作模块键（其余字段透传）
            const modKey = plain || `模块${Object.keys(out).length + 1}`;
            const mod = Object.assign({}, userData);
            if (nameField) delete mod[nameField];
            if (Object.keys(mod).length > 0) out[modKey] = mod;
          }
        }

        // 模块化结构优先：已有模块键不覆盖（防止旧用户列表转换结果覆盖较新的模块数据）
        if (map && !out['小地图']) out['小地图'] = map;
        if (charList.length && !out['角色列表']) out['角色列表'] = charList;
        if (people && !out['人物']) out['人物'] = people;
        if (base && !out['据点']) out['据点'] = base;
        if (action && !out['行动选项']) out['行动选项'] = action;

        return { 状态栏: out };
      }

      // ---------- MMS v2：命令引擎 ----------

      // 解析属性命令串：返回 [{key, op, value}]，op ∈ delta/add/set/raw
      function mmsParseAttrCommands(str) {
        const segments = String(str || '').match(/\[([^\[\]]+)\]/g) || [];
        const cmds = [];
        for (const seg of segments) {
          const content = seg.slice(1, -1).trim();
          if (!content) continue;
          if (mmsIsEmojiOnly(content)) continue; // 纯emoji装饰段
          let m = content.match(/^(.+?)\s*([+-])\s*(\d+(?:\.\d+)?)$/);
          if (m) {
            cmds.push({ key: m[1].trim(), op: m[2] === '-' ? 'delta' : 'add', value: parseFloat(m[3]) });
            continue;
          }
          m = content.match(/^(.+?)\s*[:：]\s*(.+)$/);
          if (m) {
            cmds.push({ key: m[1].trim(), op: 'set', value: m[2].trim() });
            continue;
          }
          cmds.push({ key: content, op: 'raw' });
        }
        return cmds;
      }

      function mmsAttrNormKey(key) {
        return mmsNormalizeName(key);
      }

      // 解析已存储的属性串：[{display, value}]
      function mmsParseAttrList(str) {
        const segments = String(str || '').match(/\[([^\[\]]+)\]/g) || [];
        const attrs = [];
        for (const seg of segments) {
          const content = seg.slice(1, -1).trim();
          if (!content) continue;
          const m = content.match(/^(.+?)\s*[:：]\s*(.+)$/);
          if (m) attrs.push({ display: m[1].trim(), value: m[2].trim() });
        }
        return attrs;
      }

      function mmsAttrToNumber(v) {
        const m = String(v || '').match(/^(-?\d+(?:\.\d+)?)/);
        return m ? parseFloat(m[1]) : null;
      }

      function mmsIsCurMax(v) {
        return /^\s*-?\d+(?:\.\d+)?\s*\/\s*\d+(?:\.\d+)?\s*$/.test(String(v || ''));
      }

      function mmsClampNum(n, min, max) {
        if (max != null && n > max) n = max;
        if (min != null && n < min) n = min;
        return n;
      }

      // 应用属性命令。templateAttrs：名册模板 [{key, value}]，用于无历史时的基准
      function mmsApplyAttrCommands(prevStr, cmdStr, templateAttrs) {
        const cmdText = String(cmdStr == null ? '' : cmdStr).trim();
        if (!cmdText) return prevStr || '';
        const cmds = mmsParseAttrCommands(cmdText);
        const hasOp = cmds.some((c) => c.op !== 'raw');
        if (!hasOp) return String(cmdStr); // 全量替换

        const attrs = mmsParseAttrList(prevStr);
        const tmpl = (templateAttrs || []).filter(Boolean);
        const findAttr = (key) => {
          const nk = mmsAttrNormKey(key);
          return attrs.find((a) => mmsAttrNormKey(a.display) === nk || a.display === key);
        };
        const findTmpl = (key) => {
          const nk = mmsAttrNormKey(key);
          return tmpl.find((t) => mmsAttrNormKey(t.key) === nk || t.key === key);
        };

        for (const c of cmds) {
          if (c.op === 'raw') continue; // 命令模式中的裸段忽略
          const target = findAttr(c.key);
          const baseVal = target ? target.value : (findTmpl(c.key) || {}).value;

          if (c.op === 'set') {
            const newv = String(c.value);
            if (target) {
              // "18/18" 型：设当前值保上限；其余整体替换
              if (mmsIsCurMax(target.value) && !mmsIsCurMax(newv)) {
                const max = parseFloat(String(target.value).split('/')[1]);
                const cur = mmsClampNum(parseFloat(newv) || 0, 0, max);
                target.value = `${cur}/${max}`;
              } else {
                target.value = newv;
              }
            } else {
              const tv = baseVal;
              if (tv && mmsIsCurMax(tv) && !mmsIsCurMax(newv)) {
                const max = parseFloat(String(tv).split('/')[1]);
                const cur = mmsClampNum(parseFloat(newv) || 0, 0, max);
                attrs.push({ display: c.key, value: `${cur}/${max}` });
              } else {
                attrs.push({ display: c.key, value: newv });
              }
            }
          } else {
            // delta / add
            const sign = c.op === 'delta' ? -1 : 1;
            const delta = sign * (parseFloat(c.value) || 0);
            if (target) {
              if (mmsIsCurMax(target.value)) {
                const [curS, maxS] = String(target.value).split('/');
                const cur = mmsClampNum((parseFloat(curS) || 0) + delta, 0, parseFloat(maxS));
                target.value = `${cur}/${maxS.trim()}`;
              } else {
                const n = mmsAttrToNumber(target.value);
                if (n != null) {
                  const cur = mmsClampNum(n + delta, 0, null);
                  target.value = `${cur}`;
                } else {
                  console.warn('[MMS] 属性值非数字，忽略命令:', target.display, target.value);
                }
              }
            } else if (baseVal) {
              if (mmsIsCurMax(baseVal)) {
                const [curS, maxS] = String(baseVal).split('/');
                const cur = mmsClampNum((parseFloat(curS) || 0) + delta, 0, parseFloat(maxS));
                attrs.push({ display: c.key, value: `${cur}/${maxS.trim()}` });
              } else {
                const n = mmsAttrToNumber(baseVal);
                if (n != null) {
                  attrs.push({ display: c.key, value: `${mmsClampNum(n + delta, 0, null)}` });
                }
              }
            } else {
              console.warn('[MMS] 命令目标属性不存在且无模板:', c.key);
            }
          }
        }
        return attrs.map((a) => `[${a.display}:${a.value}]`).join('');
      }

      // 名册模板属性串：[{key,value}] → "[❤️HP:18/18][🛡️Armor:6]"
      function mmsAttrsToString(attrs) {
        return (attrs || [])
          .filter(Boolean)
          .map((a) => `[${a.key}:${a.value}]`)
          .join('');
      }

      // 解析物品清单串：{prefix, items:[{display, name, count}]}
      function mmsParseItemList(str) {
        const s = String(str || '');
        const segments = s.match(/\[([^\[\]]+)\]/g) || [];
        const items = [];
        const prefixes = [];
        for (const seg of segments) {
          const content = seg.slice(1, -1).trim();
          if (!content) continue;
          if (mmsIsEmojiOnly(content)) {
            prefixes.push(seg);
            continue;
          }
          const m = content.match(/^(.*?)\s*x\s*(\d+)\s*$/);
          if (m && m[1].trim()) {
            items.push({ display: m[1].trim(), name: m[1].trim(), count: parseInt(m[2], 10) });
          } else {
            items.push({ display: content, name: content, count: null });
          }
        }
        return { prefixes, items };
      }

      function mmsNameMatch(itemName, cmdName) {
        const a = mmsNormalizeName(itemName);
        const b = mmsNormalizeName(cmdName);
        if (!a || !b) return false;
        return a === b || a.includes(b) || b.includes(a);
      }

      // 应用物品清单命令：add/delta/set；归零移除；全量识别
      function mmsApplyItemCommands(prevStr, cmdStr) {
        const cmdText = String(cmdStr == null ? '' : cmdStr).trim();
        if (!cmdText) return prevStr || '';
        const segments = cmdText.match(/\[([^\[\]]+)\]/g) || [];
        const cmds = [];
        for (const seg of segments) {
          const content = seg.slice(1, -1).trim();
          if (!content) continue;
          if (mmsIsEmojiOnly(content)) continue; // 装饰段(如[💼])在命令模式下跳过
          let m = content.match(/^\+\s*(.+?)\s*x\s*(\d+)$/);
          if (m) { cmds.push({ name: m[1].trim(), op: 'add', count: parseInt(m[2], 10) }); continue; }
          m = content.match(/^\+\s*(.+)$/);
          if (m) { cmds.push({ name: m[1].trim(), op: 'add', count: 1 }); continue; }
          m = content.match(/^(.+?)\s*-\s*(\d+)$/);
          if (m) { cmds.push({ name: m[1].trim(), op: 'delta', count: parseInt(m[2], 10) }); continue; }
          m = content.match(/^(.+?)\s*[:：]\s*(\d+)$/);
          if (m) { cmds.push({ name: m[1].trim(), op: 'set', count: parseInt(m[2], 10) }); continue; }
          // 裸段（带xN视为获得N个，否则获得1个）
          m = content.match(/^(.+?)\s*x\s*(\d+)$/);
          if (m) { cmds.push({ name: m[1].trim(), op: 'add', count: parseInt(m[2], 10) }); continue; }
          cmds.push({ name: content, op: 'add', count: 1 });
        }
        const hasOp = cmds.some((c) => c.op !== 'raw');
        if (!cmds.length || !hasOp) return String(cmdStr); // 全量替换

        const list = mmsParseItemList(prevStr);
        for (const c of cmds) {
          const idx = list.items.findIndex((it) => mmsNameMatch(it.name, c.name));
          if (c.op === 'add') {
            if (idx >= 0) {
              const it = list.items[idx];
              it.count = (it.count == null ? 1 : it.count) + c.count;
              it.display = c.name; // 显示名跟随最近一次命令的写法
            } else {
              list.items.push({ display: c.name, name: c.name, count: c.count > 1 ? c.count : null });
            }
          } else if (c.op === 'delta') {
            if (idx >= 0) {
              const it = list.items[idx];
              if (it.count == null) {
                list.items.splice(idx, 1); // 无数量物品消耗即移除
              } else {
                it.count -= c.count;
                if (it.count <= 0) list.items.splice(idx, 1);
              }
            } else {
              console.warn('[MMS] 消耗的物品不在清单中:', c.name);
            }
          } else if (c.op === 'set') {
            if (c.count <= 0) {
              if (idx >= 0) list.items.splice(idx, 1);
            } else if (idx >= 0) {
              list.items[idx].count = c.count;
            } else {
              list.items.push({ display: c.name, name: c.name, count: c.count });
            }
          }
        }
        const parts = [];
        for (const p of list.prefixes) parts.push(p);
        for (const it of list.items) parts.push(`[${it.count != null ? `${it.display}x${it.count}` : it.display}]`);
        return parts.join('');
      }

      // 现金命令：支持 "[团队现金±N]" / "[团队现金:N]" / 裸 "+12.80"/"-12.80"/"5000美元"
      function mmsApplyCashCommand(prevStr, cmdStr) {
        const cmdText = String(cmdStr == null ? '' : cmdStr).trim();
        if (!cmdText) return prevStr || '';
        if (!cmdText.includes('[')) {
          // 裸值：带符号=增量，否则绝对值
          const m = cmdText.match(/^([+-])\s*(\d+(?:\.\d+)?)\s*(.*)$/);
          if (m && m[1]) return mmsCashCompute(prevStr, m[1] === '-' ? -parseFloat(m[2]) : parseFloat(m[2]));
          return cmdText;
        }
        const cmds = mmsParseAttrCommands(cmdText);
        const cmd = cmds.find((c) => /现金|资金|金钱/.test(c.key));
        if (!cmd) {
          const any = cmds.find((c) => c.op === 'delta' || c.op === 'add' || c.op === 'set');
          if (!any) return cmdText;
          return null; // 无匹配现金命令：由调用方保留原值
        }
        if (cmd.op === 'set') return String(cmd.value);
        if (cmd.op === 'delta') return mmsCashCompute(prevStr, -(parseFloat(cmd.value) || 0));
        if (cmd.op === 'add') return mmsCashCompute(prevStr, parseFloat(cmd.value) || 0);
        return prevStr || '';
      }

      function mmsCashCompute(prevStr, delta) {
        const s = String(prevStr || '');
        const numM = s.match(/-?\d[\d,]*(?:\.\d+)?/);
        const prevNum = numM ? parseFloat(numM[0].replace(/,/g, '')) : 0;
        const suffix = s.replace(/[\d.,\s]/g, '') || '美元';
        const result = prevNum + delta;
        const str = Math.abs(result % 1) > 1e-9 ? result.toFixed(2) : String(Math.round(result));
        return str + suffix;
      }

      // ---------- MMS v2：名册合并引擎 ----------

      function mmsIndexChars(list) {
        const map = new Map();
        for (const entry of list || []) {
          if (!entry || typeof entry !== 'object') continue;
          const c = entry['角色'] || entry['用户'] || entry;
          if (!c || typeof c !== 'object') continue;
          const nameField = mmsFindNameField(c);
          const name = nameField ? String(c[nameField] || '') : '';
          const nk = mmsNormalizeName(name);
          if (nk && !map.has(nk)) map.set(nk, c);
        }
        return map;
      }

      function mmsTemplateChar(r, displayCfg) {
        const c = {
          名字: r.name || '',
          属性: mmsAttrsToString(r.attrs),
          武器: r.weapons || '',
          物品: r.items || '',
        };
        if (r.role) c['身份'] = r.role;
        const freeFields = r.freeFields && r.freeFields.length ? r.freeFields : ['穿着', '内心'];
        for (const f of freeFields) {
          if (!f || c[f] !== undefined) continue;
          const initial = r.freeInitials && r.freeInitials[f] ? r.freeInitials[f] : '';
          c[f] = /内心/.test(f) ? displayCfg.absentText : initial;
        }
        if (r.portraitTag) c['立绘'] = r.portraitTag;
        return c;
      }

      // 据点固定模块模板：名称/现金基线 + 自定义清单字段
      function mmsTemplateBase(baseCfg) {
        const b = {};
        if (baseCfg.name) b['名称'] = baseCfg.name;
        if (baseCfg.cash) b['现金'] = baseCfg.cash;
        for (const f of baseCfg.fields || []) {
          if (f && f.key && b[f.key] === undefined) b[f.key] = f.value || '';
        }
        return b;
      }

      // 合并单个角色：base=基底（上次状态或名册模板），aiChar=AI输出（可null）
      // absenceCount: 该角色连续缺席轮数（null=非更新场景，不适用阈值）
      // threshold: 连续缺席超过该轮数才显示占位文案，之前保留上轮自由字段
      function mmsMergeChar(base, aiChar, rosterEntry, storyText, displayCfg, absenceCount, threshold) {
        const src = aiChar && typeof aiChar === 'object' ? aiChar : null;
        const b = base && typeof base === 'object' ? base : {};
        const c = {};

        c['名字'] = src && src['名字'] != null ? src['名字'] : b['名字'] != null ? b['名字'] : rosterEntry ? rosterEntry.name : '';

        const templateAttrs = rosterEntry ? rosterEntry.attrs : null;
        c['属性'] =
          src && src['属性'] != null
            ? mmsApplyAttrCommands(b['属性'] || '', src['属性'], templateAttrs)
            : b['属性'] || (templateAttrs ? mmsAttrsToString(templateAttrs) : '');
        c['武器'] =
          src && src['武器'] != null ? mmsApplyItemCommands(b['武器'] || '', src['武器']) : b['武器'] || '';
        c['物品'] =
          src && src['物品'] != null ? mmsApplyItemCommands(b['物品'] || '', src['物品']) : b['物品'] || '';

        // 自由字段：AI输出的优先
        for (const k of Object.keys(src || {})) {
          if (['名字', '属性', '武器', '物品'].includes(k)) continue;
          c[k] = src[k];
        }
        // 基底自由字段：AI未输出的保留
        for (const k of Object.keys(b)) {
          if (['名字', '属性', '武器', '物品'].includes(k)) continue;
          if (!(k in c)) c[k] = b[k];
        }

        // AI整体漏输出该角色：
        // - 缺席未超阈值（默认3轮）→ 保留上轮自由字段（内心/穿着均显示上轮相同）
        // - 超过阈值 → 内心替换为占位（名称命中正文→在场未详文案；否则→未提及文案）
        if (!src && rosterEntry) {
          const overThreshold =
            absenceCount != null && threshold != null && absenceCount > threshold;
          if (overThreshold || absenceCount == null) {
            const plain = mmsPlainName(rosterEntry.name);
            const hit = plain && storyText && storyText.includes(plain);
            c['内心'] = hit ? displayCfg.presentText : displayCfg.absentText;
          }
          // 未超阈值：c 已继承基底的内心等自由字段，什么都不做
        }
        return c;
      }

      // 名册纯增量应用：只插入缺失的固定角色；同名保留现有数据（最新输出优先）；
      // 绝不删除或改写任何已有角色——用于"添加角色立即生效"与"AI省略角色列表模块"的兜底
      function mmsApplyRosterToState(state, roster, storyText) {
        const displayCfg = {
          absentText: (roster && roster.absentText) || '本轮未提及',
          presentText: (roster && roster.presentText) || '在场·本轮未详',
        };
        const out =
          state && typeof state === 'object' ? JSON.parse(JSON.stringify(state)) : { 状态栏: {} };
        const R = out['状态栏'] && typeof out['状态栏'] === 'object' ? out['状态栏'] : (out['状态栏'] = {});
        if (!Array.isArray(R['角色列表'])) R['角色列表'] = [];
        const existing = mmsIndexChars(R['角色列表']);
        const newList = [];
        const used = new Set();
        for (const r of (roster && roster.characters) || []) {
          const nk = mmsNormalizeName(r.name);
          if (nk) used.add(nk);
          const cur = nk ? existing.get(nk) : null;
          if (cur) {
            // 同名以最新输出优先：原样保留现有数据，仅提升到名册位置
            newList.push({ 角色: cur });
          } else {
            const plain = mmsPlainName(r.name);
            const hit = plain && storyText && storyText.includes(plain);
            const t = mmsTemplateChar(r, displayCfg);
            t['内心'] = hit ? displayCfg.presentText : displayCfg.absentText;
            newList.push({ 角色: t });
          }
        }
        // 其余已有角色原样保留（顺序跟随原列表）
        for (const entry of R['角色列表']) {
          const c = entry && (entry['角色'] || entry['用户'] || entry);
          const nameField = c && typeof c === 'object' ? mmsFindNameField(c) : null;
          const nk = nameField ? mmsNormalizeName(c[nameField]) : '';
          if (nk && used.has(nk)) continue;
          newList.push(entry);
        }
        R['角色列表'] = newList;

        // 地图模块按需开启：未开启的从状态移除
        const mapsCfg = (roster && roster.maps) || {};
        if (mapsCfg.minimap === false) delete R['小地图'];
        if (!mapsCfg.bigmap) delete R['大地图'];

        // 据点固定模块：缺失字段用基线补齐（不覆盖已有值）
        const baseCfg = roster && roster.base;
        if (baseCfg && baseCfg.enabled) {
          const B = R['据点'] && typeof R['据点'] === 'object' ? R['据点'] : {};
          if (baseCfg.name && !B['名称']) B['名称'] = baseCfg.name;
          if (baseCfg.cash && !B['现金']) B['现金'] = baseCfg.cash;
          for (const f of baseCfg.fields || []) {
            if (f && f.key && (B[f.key] == null || B[f.key] === '')) B[f.key] = f.value || '';
          }
          R['据点'] = B;
        }
        return out;
      }

      // 总合并：prev=上次状态(已规范化)，aiOut=AI输出(已规范化)，roster=名册，storyText=本轮正文
      // absenceMap：缺席轮数表（对象，会被原地更新：AI输出该角色→清零，漏输出→+1），null=不计数
      function mmsMergeState(prev, aiOut, roster, storyText, absenceMap) {
        const displayCfg = {
          absentText: (roster && roster.absentText) || '本轮未提及',
          presentText: (roster && roster.presentText) || '在场·本轮未详',
        };
        const threshold =
          roster && roster.absentThreshold != null ? Number(roster.absentThreshold) : 3;
        const rosterChars = (roster && roster.characters) || [];
        const mapsCfg = roster && roster.maps ? roster.maps : {};
        const minimapOn = mapsCfg.minimap !== false;
        const bigmapOn = !!mapsCfg.bigmap;
        const baseCfg = roster && roster.base ? roster.base : null;
        const prevRoot = prev && (prev['状态栏'] || prev) ? prev['状态栏'] || prev : {};
        const aiRoot = aiOut && (aiOut['状态栏'] || aiOut) ? aiOut['状态栏'] || aiOut : {};
        const R = {};
        const out = { 状态栏: R };

        // 自由标量
        R['日期和时间'] = aiRoot['日期和时间'] != null ? aiRoot['日期和时间'] : prevRoot['日期和时间'];
        R['地点'] = aiRoot['地点'] != null ? aiRoot['地点'] : prevRoot['地点'];

        // 小地图（按需开启：关闭则不渲染不注入）
        if (minimapOn) {
          if (aiRoot['小地图'] && typeof aiRoot['小地图'] === 'object') R['小地图'] = aiRoot['小地图'];
          else if (prevRoot['小地图']) R['小地图'] = prevRoot['小地图'];
        }
        // 大地图（按需开启）
        if (bigmapOn) {
          if (aiRoot['大地图'] && typeof aiRoot['大地图'] === 'object') R['大地图'] = aiRoot['大地图'];
          else if (prevRoot['大地图']) R['大地图'] = prevRoot['大地图'];
        }

        // 角色列表
        if (Array.isArray(aiRoot['角色列表'])) {
          // AI 明确输出了角色列表：固定名册在前（名册+AI命令合并），其余以AI输出为准
          const aiChars = mmsIndexChars(aiRoot['角色列表']);
          const prevChars = mmsIndexChars(prevRoot['角色列表']);
          const list = [];
          const used = new Set();
          for (const r of rosterChars) {
            const nk = mmsNormalizeName(r.name);
            if (nk) used.add(nk);
            const ai = nk ? aiChars.get(nk) : null;
            const prevC = nk ? prevChars.get(nk) : null;
            const base = prevC || mmsTemplateChar(r, displayCfg);
            // 缺席计数：AI输出该角色→清零；漏输出→+1
            let absenceCount = null;
            if (absenceMap) {
              absenceCount = ai ? 0 : (absenceMap[nk] || 0) + 1;
              absenceMap[nk] = absenceCount;
            }
            list.push({
              角色: mmsMergeChar(base, ai, r, storyText, displayCfg, absenceCount, threshold),
            });
          }
          for (const [nk, ai] of aiChars) {
            if (used.has(nk)) continue;
            const prevC = prevChars.get(nk);
            list.push({ 角色: mmsMergeChar(prevC || {}, ai, null, storyText, displayCfg) });
          }
          if (list.length) R['角色列表'] = list;
        } else if (prevRoot['角色列表'] || rosterChars.length) {
          // AI 整体省略角色列表模块：上次角色全量保留 + 名册增量覆盖（不丢任何角色，不计数）
          const aug = mmsApplyRosterToState({ 状态栏: prevRoot }, roster, storyText);
          const augList = aug && aug['状态栏'] && aug['状态栏']['角色列表'];
          if (augList && augList.length) R['角色列表'] = augList;
        }

        // 人物（自由全量；AI省略保留上次）
        if (aiRoot['人物'] && typeof aiRoot['人物'] === 'object') R['人物'] = aiRoot['人物'];
        else if (prevRoot['人物']) R['人物'] = prevRoot['人物'];

        // 据点：现金/清单命令 + 自由字段（固定模块开启时基线补齐）
        const aiB = aiRoot['据点'] && typeof aiRoot['据点'] === 'object' ? aiRoot['据点'] : null;
        const prevB = prevRoot['据点'] && typeof prevRoot['据点'] === 'object' ? prevRoot['据点'] : null;
        if (aiB || prevB || (baseCfg && baseCfg.enabled)) {
          const a = aiB || {};
          const p = prevB || (baseCfg && baseCfg.enabled ? mmsTemplateBase(baseCfg) : {});
          const B = {};
          const cashCmd = a['现金'] != null ? mmsApplyCashCommand(p['现金'] || '', a['现金']) : null;
          B['名称'] = a['名称'] != null ? a['名称'] : p['名称'];
          B['现金'] = cashCmd != null ? cashCmd : p['现金'];
          // 清单字段 = 固定模块字段 + 状态中已有的清单字段（载具/武器/防御/杂物兼容）
          const listFields = new Set(['载具', '武器', '防御', '杂物']);
          for (const f of baseCfg && baseCfg.enabled ? baseCfg.fields || [] : []) {
            if (f && f.key) listFields.add(f.key);
          }
          for (const f of listFields) {
            B[f] = a[f] != null ? mmsApplyItemCommands(p[f] || '', a[f]) : p[f];
          }
          // 额外键透传
          for (const k of Object.keys(a)) {
            if (k === '名称' || k === '现金' || listFields.has(k)) continue;
            B[k] = a[k];
          }
          for (const k of Object.keys(p)) {
            if (k === '名称' || k === '现金' || listFields.has(k)) continue;
            if (!(k in B)) B[k] = p[k];
          }
          R['据点'] = B;
        }

        // 行动选项（自由全量；AI省略保留上次）
        if (aiRoot['行动选项']) R['行动选项'] = aiRoot['行动选项'];
        else if (prevRoot['行动选项']) R['行动选项'] = prevRoot['行动选项'];

        // 自定义模块：AI输出透传；AI省略保留上次（累积内容不丢失）
        // 注意：用户列表是旧格式遗留键，已在 MMS_KNOWN_MODULES 中标记为已知，
        // 此处不会作为自定义模块透传（normalizeState 负责转换为模块化结构）
        for (const k of Object.keys(aiRoot)) {
          if (MMS_KNOWN_MODULES.includes(k)) continue;
          R[k] = aiRoot[k];
        }
        for (const k of Object.keys(prevRoot)) {
          if (MMS_KNOWN_MODULES.includes(k)) continue;
          if (!(k in R)) R[k] = prevRoot[k];
        }
        return out;
      }

      // ---------- 更新器系统提示词（v3：按玩家设置动态拼装，不硬编码模块结构） ----------

      // 依据名册（角色自由字段并集）、据点固定模块、地图开关与标签分配，动态生成发送给更新 LLM 的系统提示词
      function mmsBuildSystemPrompt(roster) {
        roster = roster || {};
        const maps = roster.maps || {};
        const minimapOn = maps.minimap !== false;
        const bigmapOn = !!maps.bigmap;
        const base = roster.base || {};
        const baseOn = !!base.enabled;
        const charMode = roster.charDisplayMode === 'fixed' ? 'fixed' : 'full';
        const tagCfg = mmsGetMapTags(roster);
        const miniTags = tagCfg.mini.join('、');
        const bigTags = tagCfg.big.join('、');

        // 角色自由字段：名册并集，默认穿着/内心
        const freeSet = [];
        const rosterNames = [];
        for (const r of roster.characters || []) {
          if (r && r.name) rosterNames.push(mmsPlainName(r.name) || r.name);
          for (const f of (r && r.freeFields) || []) {
            if (f && freeSet.indexOf(f) === -1) freeSet.push(f);
          }
        }
        const freeFields = freeSet.length ? freeSet : ['穿着', '内心'];
        const charFreeList = freeFields.join('、');
        const charFieldJson = freeFields.map((f) => '"' + f + '": "…"').join(', ');

        const baseFieldKeys = (base.fields || []).map((f) => f && f.key).filter(Boolean);
        const baseFieldList = baseFieldKeys.join('、');
        const baseFieldJson = baseFieldKeys.map((k) => '"' + k + '": "…"').join(', ');
        const rosterList = rosterNames.length ? rosterNames.join('、') : '（名册为空）';

        const lines = [];
        lines.push('你是跑团状态栏数据管理员。依据「最新剧情」把「当前状态」更新为新状态，输出一个 JSON 对象（顶层键为「状态栏」）。固定成员名单见用户消息。');
        lines.push('');
        lines.push('## 状态栏模块结构');
        lines.push('{');
        lines.push('  "状态栏": {');
        lines.push('    "日期和时间": "⏰ …",');
        lines.push('    "地点": "📍 …",');
        if (minimapOn) lines.push('    "小地图": { "场景键": ["Emoji【名称】(x, y) 一句话描述"] },');
        if (bigmapOn) lines.push('    "大地图": { "场景键": ["Emoji【名称】(x, y) 一句话描述"] },');
        lines.push(
          '    "角色列表": [ { "角色": { "名字": "…", "属性": "…"' +
            (charFieldJson ? ', ' + charFieldJson : '') +
            ', "武器": "…", "物品": "…" } } ],',
        );
        lines.push('    "人物": { "盟友": ["…"], "NPC": ["…"], "敌人": ["…"] },');
        if (baseOn) {
          lines.push(
            '    "据点": { "名称": "…", "现金": "…"' +
              (baseFieldJson ? ', ' + baseFieldJson : '') +
              ' },',
          );
        }
        lines.push('    "行动选项": { "名字": "🧑 团队行动", "选项": ["1. …", "2. …", "3. …", "4. …"] }');
        lines.push('  }');
        lines.push('}');
        if (minimapOn) {
          lines.push('- 小地图场景键沿用当前状态；确需更换只能从以下选择：' + (miniTags || '（无可用标签）') + '。坐标为 ' + MMS_COORD_MIN + '~' + MMS_COORD_MAX + ' 的整数。');
          lines.push('- 小地图描述：简单描述角色的状态和位置（如"站在大树后，精神紧绷"）。');
        }
        if (bigmapOn) {
          lines.push('- 大地图用于更大范围的区域/全局场景（城市、荒野全图等），场景键只能从以下选择：' + (bigTags || '（无可用标签）') + '。坐标为 ' + MMS_COORD_MIN + '~' + MMS_COORD_MAX + ' 的整数。');
        }
        lines.push('- 人物描述：描述NPC的简单动作（如"拿起一杯茶，想继续了解玛德琳的情报"）。与小地图不同，人物侧重行为意图而非位置状态。');
        lines.push('- 角色自由字段：' + charFreeList + '（贴合剧情每轮全量输出）。');
        if (baseOn) {
          lines.push('- 据点字段：名称为自由文本；现金与' + (baseFieldList || '清单字段') + '为数值/清单字段。');
        }
        lines.push('- 若当前状态中存在其他自定义模块（如线索、情报等' + (baseOn ? '' : '、据点') + '），按其原有结构全量输出，不要丢弃。');
        lines.push('- 各模块描述格式沿用当前状态的风格（emoji、【】名称、[ ]物品括号等）。');
        lines.push('');
        lines.push('## 校验字段：只输出命令，禁止全量重写');
        const checkTargets = ['角色列表的「属性」「武器」「物品」'];
        if (baseOn) {
          checkTargets.push('据点的「现金」' + (baseFieldList ? '与「' + baseFieldKeys.join('」「') + '」' : ''));
        }
        lines.push('适用于：' + checkTargets.join('，') + '。');
        lines.push('- 属性命令："[键-N]"减少 / "[键+N]"增加 / "[键:值]"设值。键用裸名（不带emoji）。值为"当前/上限"格式时命令只作用于当前值。');
        lines.push('  例：`"属性": "[HP-2][SAN:55]"`');
        lines.push('- 物品命令："[+名称]"获得 / "[+名称xN]"获得N个 / "[名称-N]"消耗 / "[名称:N]"设为数量。');
        lines.push('  例：`"物品": "[+.45子弹x100][绷带-1]"`。数量归零的物品会被自动移除。');
        lines.push('- 现金命令同属性语法："[团队现金-12.80]" / "[团队现金:5000]"。');
        lines.push('- 剧情没有变化的校验字段：整个字段省略不输出（程序会保持原值）。');
        if (charMode === 'fixed') {
          lines.push('- 角色列表只可显示固定成员：' + rosterList + '。其余新登场角色放入「人物」中缩略显示（格式与盟友/NPC一致），不要在角色列表中输出。');
        } else {
          lines.push('- 角色列表可显示固定成员：' + rosterList + '。新登场的关键NPC（当前状态与固定成员中都不存在）：属性输出完整值（如 "[❤️HP:12/12][🛡️Armor:2]"），武器/物品输出完整清单。其余非重要角色放入「人物」中缩略显示。');
        }
        if (!baseOn) {
          lines.push('- 若当前状态中存在「据点」模块，其「现金」与清单字段同样适用命令协议。');
        }
        lines.push('');
        lines.push('## 自由字段：每轮全量输出');
        const freeListParts = ['日期和时间', '地点'];
        if (minimapOn) freeListParts.push('小地图');
        if (bigmapOn) freeListParts.push('大地图');
        freeListParts.push('人物（盟友/NPC/敌人）', '行动选项');
        if (baseOn) freeListParts.push('据点的名称');
        lines.push(freeListParts.join('、') + '，角色的' + charFreeList + '，以及所有自定义模块。未提及的人物条目从对应数组移除，新登场的加入。');
        lines.push('');
        lines.push('## 固定成员规则（名单见用户消息）');
        lines.push('- 剧情提及固定成员 → 输出其条目（校验字段用命令，自由字段全量）。');
        lines.push('- 剧情明确显示其不在场 → 输出条目且内心字段写"不在场"，其余字段省略。');
        lines.push('- 剧情完全未提及 → 整个条目省略（程序自动保留其上次数值并标注）。');
        lines.push('');
        lines.push('## 输出要求');
        lines.push('只输出 JSON 本体，禁止解释文字与 markdown 代码块。保持当前状态的模块顺序、字段命名与 emoji 风格。');
        return lines.join('\n');
      }

      const MMS = {
        floorId: null,
        messageText: '',
        isLastAssistantFloor: false,
        updating: false,

        env: {
          hasMessageApi: false,
          hasVarsApi: false,
          hasGenApi: false,
          hasInjectApi: false,
          hasEventApi: false,
          hasSetChatApi: false,
        },

        detectEnv() {
          this.env.hasMessageApi =
            typeof getCurrentMessageId === 'function' && typeof getChatMessages === 'function';
          this.env.hasVarsApi =
            typeof getVariables === 'function' && typeof insertOrAssignVariables === 'function';
          this.env.hasGenApi = typeof generateRaw === 'function' || typeof generate === 'function';
          this.env.hasInjectApi =
            typeof injectPrompts === 'function' && typeof uninjectPrompts === 'function';
          this.env.hasEventApi = typeof eventOn === 'function' && typeof eventEmit === 'function';
          this.env.hasSetChatApi = typeof setChatMessages === 'function';
        },

        // ---------- 工具 ----------

        hashStr(str) {
          let h = 5381;
          const s = String(str || '');
          for (let i = 0; i < s.length; i++) {
            h = ((h << 5) + h + s.charCodeAt(i)) | 0;
          }
          return String(h);
        },

        stateToYaml(state) {
          return jsyaml.dump(state, { lineWidth: -1, noRefs: true });
        },

        setIndicator(kind, title) {
          const el = document.getElementById('mms-update-indicator');
          if (!el) return;
          if (!kind) {
            el.style.display = 'none';
            el.className = 'mms-indicator';
            return;
          }
          el.style.display = 'inline-block';
          el.className = 'mms-indicator ' + kind;
          el.title = title || '';
        },

        // ---------- 配置（全局变量，跨聊天、跨设备跟随用户存档） ----------

        loadConfig() {
          const defaults = {
            autoUpdate: true,
            apiUrl: '',
            apiKey: '',
            model: '',
            source: 'custom',
            preset: '',
            contextFloors: 2,
            temperature: 0.3,
            maxTokens: 4096,
            corePrompt: '',
            systemPrompt: '',
            debug: false,
          };
          try {
            if (!this.env.hasVarsApi) return defaults;
            const g = getVariables({ type: 'global' }) || {};
            const cfg = g && typeof g.$mms_config === 'object' ? g.$mms_config : {};
            return Object.assign({}, defaults, cfg);
          } catch (e) {
            return defaults;
          }
        },

        // ---------- 提示词预设（下拉栏，含锁定的动态默认） ----------

        loadPromptPresets() {
          const fallback = {
            active: 'default',
            presets: [{ id: 'default', name: '默认协议（动态）', content: '', locked: true }],
          };
          try {
            if (!this.env.hasVarsApi) return fallback;
            const g = getVariables({ type: 'global' }) || {};
            const p = g && g.$mms_prompt_presets;
            if (!p || typeof p !== 'object' || !Array.isArray(p.presets)) return fallback;
            // 确保默认预设始终在首位
            const presets = p.presets.filter(Boolean);
            if (!presets.some((x) => x.id === 'default')) {
              presets.unshift({ id: 'default', name: '默认协议（动态）', content: '', locked: true });
            }
            return { active: p.active || 'default', presets };
          } catch (e) {
            return fallback;
          }
        },

        savePromptPresets(data) {
          try {
            if (!this.env.hasVarsApi) return;
            insertOrAssignVariables({ $mms_prompt_presets: data }, { type: 'global' });
          } catch (e) {
            console.error('[MMS] 保存提示词预设失败:', e);
          }
        },

        // ---------- API 预设（下拉栏，含锁定的默认连接） ----------

        loadApiPresets() {
          const fallback = {
            active: 'default',
            presets: [
              {
                id: 'default',
                name: '默认（当前酒馆连接）',
                config: {},
                locked: true,
              },
            ],
          };
          try {
            if (!this.env.hasVarsApi) return fallback;
            const g = getVariables({ type: 'global' }) || {};
            const p = g && g.$mms_api_presets;
            if (!p || typeof p !== 'object' || !Array.isArray(p.presets)) return fallback;
            const presets = p.presets.filter(Boolean);
            if (!presets.some((x) => x.id === 'default')) {
              presets.unshift({ id: 'default', name: '默认（当前酒馆连接）', config: {}, locked: true });
            }
            return { active: p.active || 'default', presets };
          } catch (e) {
            return fallback;
          }
        },

        saveApiPresets(data) {
          try {
            if (!this.env.hasVarsApi) return;
            insertOrAssignVariables({ $mms_api_presets: data }, { type: 'global' });
          } catch (e) {
            console.error('[MMS] 保存API预设失败:', e);
          }
        },

        // ---------- 预设 JSON 文件导入/导出 ----------

        exportPresetFile(data, filename) {
          try {
            const json = JSON.stringify(data, null, 2);
            const blob = new Blob([json], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = filename;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            setTimeout(() => URL.revokeObjectURL(url), 1000);
          } catch (e) {
            alert('导出失败：' + e.message);
          }
        },

        importPresetFile(accept, callback) {
          const input = document.createElement('input');
          input.type = 'file';
          input.accept = accept;
          input.style.display = 'none';
          input.addEventListener('change', () => {
            const file = input.files && input.files[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = () => {
              try {
                callback(JSON.parse(reader.result));
              } catch (e) {
                alert('JSON 解析失败：' + e.message);
              }
            };
            reader.readAsText(file);
            document.body.removeChild(input);
          });
          document.body.appendChild(input);
          input.click();
        },

        saveConfig(cfg) {
          try {
            if (!this.env.hasVarsApi) return;
            insertOrAssignVariables({ $mms_config: cfg }, { type: 'global' });
          } catch (e) {
            console.error('[MMS] 保存配置失败:', e);
          }
        },

        // ---------- 固定角色名册（聊天变量，随聊天导出） ----------

        loadRoster() {
          const fallback = {
            characters: [],
            absentText: '本轮未提及',
            presentText: '在场·本轮未详',
            absentThreshold: 3,
            charDisplayMode: 'full', // full=全显模式 / fixed=固定模式
            base: { enabled: false, name: '', cash: '', fields: [] },
            maps: { minimap: true, bigmap: false },
            mapTags: { pool: [], mini: MMS_MINI_DEFAULT_TAGS.slice(), big: [] },
          };
          try {
            if (!this.env.hasVarsApi) return fallback;
            const chatVars = getVariables({ type: 'chat' }) || {};
            const r = chatVars && chatVars.$mms_roster;
            if (!r || typeof r !== 'object') return fallback;
            const t = parseInt(r.absentThreshold, 10);
            const base =
              r.base && typeof r.base === 'object'
                ? {
                    enabled: !!r.base.enabled,
                    name: r.base.name || '',
                    cash: r.base.cash || '',
                    fields: Array.isArray(r.base.fields) ? r.base.fields.filter(Boolean) : [],
                  }
                : fallback.base;
            const maps =
              r.maps && typeof r.maps === 'object'
                ? { minimap: r.maps.minimap !== false, bigmap: !!r.maps.bigmap }
                : fallback.maps;
            const tagCfg = mmsGetMapTags(r);
            return {
              characters: Array.isArray(r.characters) ? r.characters.filter(Boolean) : [],
              absentText: r.absentText || fallback.absentText,
              presentText: r.presentText || fallback.presentText,
              absentThreshold: isNaN(t) ? fallback.absentThreshold : t,
              charDisplayMode: r.charDisplayMode === 'fixed' ? 'fixed' : 'full',
              base: base,
              maps: maps,
              mapTags: tagCfg,
            };
          } catch (e) {
            console.warn('[MMS] 读取名册失败:', e);
            return fallback;
          }
        },

        // 缺席轮数表（聊天变量 $mms_absence：{ 名字规范化键: 连续缺席轮数 }）
        loadAbsence() {
          try {
            if (!this.env.hasVarsApi) return {};
            const chatVars = getVariables({ type: 'chat' }) || {};
            const a = chatVars && chatVars.$mms_absence;
            return a && typeof a === 'object' ? a : {};
          } catch (e) {
            return {};
          }
        },

        saveAbsence(absence) {
          try {
            if (!this.env.hasVarsApi) return;
            insertOrAssignVariables({ $mms_absence: absence || {} }, { type: 'chat' });
          } catch (e) {
            console.warn('[MMS] 保存缺席轮数失败:', e);
          }
        },

        saveRoster(roster) {
          try {
            if (!this.env.hasVarsApi) return;
            insertOrAssignVariables({ $mms_roster: roster }, { type: 'chat' });
          } catch (e) {
            console.error('[MMS] 保存名册失败:', e);
          }
        },

        buildCustomApi(cfg) {
          const api = {};
          if (cfg.preset && cfg.preset.trim()) api.proxy_preset = cfg.preset.trim();
          if (cfg.apiUrl && cfg.apiUrl.trim()) {
            api.apiurl = cfg.apiUrl.trim();
            if (cfg.apiKey) api.key = cfg.apiKey;
            api.source = cfg.source || 'custom';
          }
          if (cfg.model && cfg.model.trim()) api.model = cfg.model.trim();
          api.temperature = typeof cfg.temperature === 'number' ? cfg.temperature : 0.3;
          api.max_tokens = cfg.maxTokens || 4096;
          return api;
        },

        // ---------- 状态读写 ----------

        readFloorVars(floorId) {
          try {
            if (!this.env.hasVarsApi || floorId == null) return null;
            return getVariables({ type: 'message', message_id: floorId }) || null;
          } catch (e) {
            console.warn('[MMS] 读取楼层变量失败:', e);
            return null;
          }
        },

        writeState(floorId, state) {
          // 写入前统一规范化，确保存储的永远是干净的模块化格式（无旧用户列表残留）
          const normalized = mmsNormalizeState(state) || state;
          const vars = {
            stat_data: normalized,
            $mms_meta: { hash: this.hashStr(this.messageText), ts: Date.now() },
          };
          insertOrAssignVariables(vars, { type: 'message', message_id: floorId });
        },

        // 从目标楼层往前找最近一份状态：优先变量快照，其次旧式 Status_block 文本
        async findPrevState(floorId) {
          try {
            if (typeof getLastMessageId !== 'function') return null;
            const last = getLastMessageId();
            // 最多回溯 50 楼：避免超长聊天在无数据时全量遍历
            const stop = Math.max(0, floorId - 50);
            for (let id = Math.min(floorId - 1, last); id >= stop; id--) {
              if (this.env.hasVarsApi) {
                const vars = this.readFloorVars(id);
                if (vars && vars.stat_data) {
                  const normalized = mmsNormalizeState(vars.stat_data);
                  if (normalized) return { floorId: id, state: normalized };
                }
              }
              const legacy = this.readLegacyState(id);
              if (legacy) return { floorId: id, state: legacy };
            }
          } catch (e) {
            console.warn('[MMS] 查找历史状态失败:', e);
          }
          return null;
        },

        readLegacyState(floorId) {
          try {
            if (typeof getChatMessages !== 'function') return null;
            const arr = getChatMessages(floorId);
            const m = Array.isArray(arr) && arr.length > 0 ? arr[0] : arr;
            if (!m || typeof m.message !== 'string') return null;
            const raw = extractStatusBlock(m.message);
            if (!raw) return null;
            const parsed = jsyaml.load(raw);
            if (!parsed || Object.keys(parsed).length === 0) return null;
            return mmsNormalizeState(parsed) || parsed;
          } catch (e) {
            return null;
          }
        },

        // ---------- 渲染 ----------

        renderFromState(state) {
          try {
            updateYamlDataSource(this.stateToYaml(state));
            setTimeout(() => reRenderStatusBar(), 60);
          } catch (e) {
            console.error('[MMS] 状态渲染失败:', e);
          }
        },

        refreshFromVars() {
          if (this.floorId == null) return;
          const vars = this.readFloorVars(this.floorId);
          if (vars && vars.stat_data) {
            this.renderFromState(mmsNormalizeState(vars.stat_data) || vars.stat_data);
          }
        },

        // ---------- 深度 0 系统注入 ----------

        ensureInjection(state, floorId) {
          if (!this.env.hasInjectApi || !state) return;
          try {
            const rootKey = Object.keys(state)[0];
            if (!rootKey) return;
            const injectable = JSON.parse(JSON.stringify(state));
            const root = injectable[rootKey];
            if (root && typeof root === 'object' && !Array.isArray(root)) {
              delete root['行动选项'];
            }
            const yaml = this.stateToYaml(injectable);
            const content =
              '<当前状态数据（系统自动维护，反映最新楼层结束时的状态）>\n' +
              yaml +
              '\n</当前状态数据>';
            uninjectPrompts([MMS_INJECT_ID]);
            injectPrompts([
              {
                id: MMS_INJECT_ID,
                position: 'in_chat',
                depth: 0,
                role: 'system',
                content,
                should_scan: true,
              },
            ]);
          } catch (e) {
            console.warn('[MMS] 状态注入失败:', e);
          }
        },

        // ---------- 楼层判断与剧情收集 ----------

        checkLastAssistantFloor(floorId) {
          try {
            if (typeof getLastMessageId !== 'function') return false;
            const last = getLastMessageId();
            if (last <= floorId) return true;
            const arr = getChatMessages(`${floorId + 1}-${last}`);
            const msgs = Array.isArray(arr) ? arr : [arr];
            return !msgs.some((m) => m && (m.role === 'assistant' || (!m.role && !m.is_user)));
          } catch (e) {
            return false;
          }
        },

        readFloorMaintext(floorId) {
          try {
            if (typeof getChatMessages !== 'function') return '';
            const arr = getChatMessages(floorId);
            const m = Array.isArray(arr) && arr.length > 0 ? arr[0] : arr;
            if (!m || typeof m.message !== 'string') return '';
            let text = extractLastBlock(m.message, 'maintext');
            if (!text) {
              text = m.message.replace(/<Status_block>[\s\S]*?<\/Status_block>/gi, '');
            }
            text = text.replace(/\[IMG_GEN\][\s\S]*?\[\/IMG_GEN\]/gi, '');
            text = text.replace(/【状态栏标记点】/g, '');
            return text.trim();
          } catch (e) {
            return '';
          }
        },

        // 收集最近 N 层 AI 剧情正文：最新一层（据此更新）+ 前情（仅参考）
        collectStorySegments(targetFloorId, n = 2) {
          const latest = this.readFloorMaintext(targetFloorId);
          let context = '';
          try {
            if (typeof getLastMessageId !== 'function' || n <= 1) return { latest, context };
            const parts = [];
            let id = targetFloorId - 1;
            let need = n - 1;
            while (id >= 0 && need > 0) {
              const arr = getChatMessages(id);
              const m = Array.isArray(arr) && arr.length > 0 ? arr[0] : arr;
              if (m && (m.role === 'assistant' || (!m.role && !m.is_user))) {
                const t = this.readFloorMaintext(id);
                if (t) {
                  parts.unshift(t);
                  need--;
                }
              }
              id--;
            }
            context = parts.join('\n\n');
          } catch (e) {
            context = '';
          }
          return { latest, context };
        },

        // ---------- 独立 LLM 更新 ----------

        parseStateOutput(raw) {
          let text = String(raw || '').trim();
          // 剥掉可能的 markdown 代码围栏
          text = text.replace(/^```[a-zA-Z]*\s*\n?/, '').replace(/\n?```\s*$/, '');
          // 截取首个 { 到最后一个 }
          const first = text.indexOf('{');
          const last = text.lastIndexOf('}');
          if (first === -1 || last === -1 || last <= first) {
            throw new Error('AI 输出中未找到 JSON 对象');
          }
          let jsonText = text.slice(first, last + 1);
          const state = JSON.parse(jsonText);
          if (!state || typeof state !== 'object' || Array.isArray(state)) {
            throw new Error('JSON 顶层不是对象');
          }
          // 空对象/无有效模块的输出视为失败（防止垃圾输出清空整楼状态）
          const root = state['状态栏'] && typeof state['状态栏'] === 'object' ? state['状态栏'] : state;
          const knownModules = MMS_KNOWN_MODULES;
          const hasKnown = Object.keys(root).some((k) => knownModules.includes(k));
          if (!hasKnown) {
            throw new Error('AI 输出不含任何状态栏模块（疑似空/垃圾输出）');
          }
          return state;
        },

        sanitizeState(state) {
          const clamp = (v) =>
            Math.max(MMS_COORD_MIN, Math.min(MMS_COORD_MAX, Math.round(Number(v) || 0)));
          // 递归重写：把含【名称】的地图行中的 (x, y) 坐标夹取到约定范围
          const fixValue = (value) => {
            if (Array.isArray(value)) {
              return value.map(fixValue);
            }
            if (value && typeof value === 'object') {
              const out = {};
              for (const k of Object.keys(value)) {
                out[k] = fixValue(value[k]);
              }
              return out;
            }
            if (typeof value === 'string') {
              const m = value.match(/\(\s*(-?\d+)\s*,\s*(-?\d+)\s*\)/);
              if (m && /【.+?】/.test(value)) {
                return value.replace(
                  /\(\s*(-?\d+)\s*,\s*(-?\d+)\s*\)/,
                  `(${clamp(m[1])}, ${clamp(m[2])})`,
                );
              }
              return value;
            }
            return value;
          };
          const rootKey = Object.keys(state)[0];
          if (rootKey && state[rootKey] && typeof state[rootKey] === 'object') {
            state[rootKey] = fixValue(state[rootKey]);
          }
          return state;
        },

        async runUpdate(targetFloorId, options = {}) {
          const { manual = false } = options;
          if (!this.env.hasGenApi || !this.env.hasVarsApi) {
            if (manual) alert('当前酒馆助手版本缺少 generateRaw 或变量接口，无法独立更新状态');
            return false;
          }
          if (this.updating) {
            if (manual) alert('状态更新正在进行中，请稍候');
            return false;
          }

          const cfg = this.loadConfig();
          this.updating = true;
          this.setIndicator('updating', '正在通过独立 AI 更新状态…');
          try {
            const prev = await this.findPrevState(targetFloorId);
            const roster = this.loadRoster();
            const prevYaml = prev
              ? this.stateToYaml(prev.state)
              : '（暂无初始状态，请依据剧情建立完整状态栏）';
            const floorCount = Math.min(10, Math.max(1, Number(cfg.contextFloors) || 2));
            const { latest, context } = this.collectStorySegments(targetFloorId, floorCount);

            let userPrompt = '<当前状态>\n' + prevYaml + '\n</当前状态>\n\n';
            // 固定成员名册段：告知更新 AI 常驻角色及其校验属性键
            if (roster.characters.length) {
              userPrompt +=
                '<固定成员（剧情提及必须输出其条目：校验字段用命令、自由字段全量；剧情明确不在场时内心写"不在场"并可省略其余字段；完全未提及则整个条目省略）>\n';
              for (const r of roster.characters) {
                const keys = (r.attrs || []).map((a) => a.key).join('、');
                const free = (r.freeFields && r.freeFields.length ? r.freeFields : ['穿着', '内心']).join('、');
                userPrompt += '- ' + (mmsPlainName(r.name) || r.name) + '（属性键：' + (keys || '无') + '；自由字段：' + free + '）\n';
              }
              userPrompt += '</固定成员>\n\n';
            }
            if (context) {
              userPrompt +=
                '<前情提要（仅作背景参考，其变化已计入当前状态，不要重复应用）>\n' +
                context +
                '\n</前情提要>\n\n';
            }
            userPrompt +=
              '<最新剧情（请依据这段剧情更新状态）>\n' +
              (latest || '（无剧情正文，请保持当前状态并完善行动选项）') +
              '\n</最新剧情>\n\n请输出更新后的完整状态栏 JSON。';

            const customApi = this.buildCustomApi(cfg);
            // 系统提示词 = 当前激活的提示词预设（默认预设动态拼装；自定义预设为固定存储内容）
            const ps = this.loadPromptPresets();
            const activePreset = ps.presets.find((p) => p.id === ps.active) || ps.presets[0];
            const sysPrompt =
              activePreset && !activePreset.locked && activePreset.content
                ? activePreset.content
                : mmsBuildSystemPrompt(roster);
            let lastError = null;

            for (let attempt = 0; attempt < 3; attempt++) {
              try {
                const config = {
                  ordered_prompts: [
                    { role: 'system', content: sysPrompt },
                    { role: 'user', content: userPrompt },
                  ],
                  custom_api: customApi,
                  should_silence: true,
                  generation_id: 'mms-update-' + targetFloorId + '-' + Date.now(),
                };
                // 首次尝试带结构化约束；部分端点不支持时自动降级为纯提示词
                if (attempt === 0) config.json_schema = MMS_JSON_SCHEMA;

                const result = await generateRaw(config);
                const raw = typeof result === 'string' ? result : (result && result.content) || '';
                // Debug：记录本次请求的完整提示词与原始返回
                this.debugLog(sysPrompt, userPrompt, raw, customApi);
                const parsed = this.parseStateOutput(raw);
                const aiState = mmsNormalizeState(parsed) || parsed;
                // 合并：校验命令应用 + 固定名册 + 自定义模块兜底 + 缺席轮数维护
                const absence = this.loadAbsence();
                const state = mmsMergeState(
                  prev ? prev.state : null,
                  aiState,
                  roster,
                  latest || '',
                  absence,
                );
                this.saveAbsence(absence);
                this.sanitizeState(state);

                this.writeState(targetFloorId, state);

                const isLatest = this.checkLastAssistantFloor(targetFloorId);
                if (isLatest) this.ensureInjection(state, targetFloorId);

                if (targetFloorId === this.floorId) this.refreshFromVars();
                if (this.env.hasEventApi) {
                  eventEmit(MMS_EVENT_UPDATED, { message_id: targetFloorId, state });
                }

                this.setIndicator('ok', '状态已更新');
                setTimeout(() => {
                  if (!this.updating) this.setIndicator(null);
                }, 4000);
                return true;
              } catch (e) {
                lastError = e;
                console.warn('[MMS] 更新失败（第 ' + (attempt + 1) + ' 次）：', e);
                if (attempt < 2) await new Promise((r) => setTimeout(r, 1000 * (attempt + 1)));
              }
            }
            throw lastError || new Error('未知错误');
          } catch (e) {
            const msg = e && e.message ? e.message : String(e);
            console.error('[MMS] 状态更新最终失败:', e);
            this.setIndicator('error', '更新失败：' + msg + '（点击重试）');
            if (this.env.hasEventApi) {
              eventEmit(MMS_EVENT_FAILED, { message_id: targetFloorId, error: msg });
            }
            return false;
          } finally {
            this.updating = false;
          }
        },

        maybeAutoUpdate() {
          const cfg = this.loadConfig();
          if (!cfg.autoUpdate) return false;
          if (!this.isLastAssistantFloor) return false;
          // 独立 API 未配置且未配置代理预设时也可运行（使用当前酒馆连接）
          setTimeout(() => this.runUpdate(this.floorId), 300);
          return true;
        },

        // ---------- 标记点漂移兜底 ----------

        setupDriftGuard() {
          // 由“最新 AI 楼层”的小部件注册（新楼层到达时它仍在渲染中）：
          // 若新楼层既无标记点也无 Status_block（正文 AI 漂移），补写标记点，保证小部件能渲染
          if (!this.env.hasEventApi || !this.env.hasSetChatApi || !this.isLastAssistantFloor) return;
          if (typeof getChatMessages !== 'function') return;
          const ev =
            (typeof tavern_events !== 'undefined' && tavern_events && tavern_events.MESSAGE_RECEIVED) ||
            'message_received';
          try {
            eventOn(ev, async (messageId) => {
              try {
                if (messageId == null) return;
                const arr = getChatMessages(messageId);
                const m = Array.isArray(arr) && arr.length > 0 ? arr[0] : arr;
                if (!m || typeof m.message !== 'string') return;
                if (m.role === 'user' || m.is_user) return;
                if (m.message.includes(MMS_MARKER) || /<Status_block>/i.test(m.message)) return;
                // 跨组件去重锁（多个楼层小部件同时监听时只补写一次）
                if (this.env.hasVarsApi) {
                  const chatVars = getVariables({ type: 'chat' }) || {};
                  const lock = chatVars && chatVars.$mms_drift_lock;
                  if (lock && lock.mid === messageId && Date.now() - lock.ts < 60000) return;
                  insertOrAssignVariables(
                    { $mms_drift_lock: { mid: messageId, ts: Date.now() } },
                    { type: 'chat' },
                  );
                }
                await setChatMessages(
                  [{ message_id: messageId, message: m.message + '\n\n' + MMS_MARKER }],
                  { refresh: 'affected' },
                );
                console.info('[MMS] 已为新楼层补写状态栏标记点');
              } catch (e) {
                console.warn('[MMS] 标记点兜底失败:', e);
              }
            });
          } catch (e) {
            /* 事件系统不可用则跳过 */
          }
        },

        // ---------- YAML 编辑模式 ----------

        async openEditMode() {
          if (!this.env.hasVarsApi) {
            alert('当前环境不支持变量写入，无法编辑');
            return;
          }
          let yamlText = '';
          const vars = this.floorId != null ? this.readFloorVars(this.floorId) : null;
          if (vars && vars.stat_data) {
            yamlText = this.stateToYaml(vars.stat_data);
          } else {
            const legacy = extractStatusBlock(this.messageText);
            yamlText = legacy || '# 未找到状态数据。首次使用请先「从本楼导入」或「立即更新」。\n';
          }
          const editor = document.getElementById('mms-yaml-editor');
          if (editor) editor.value = yamlText.trim() + '\n';
          const main = document.getElementById('mms-main-view');
          const edit = document.getElementById('mms-edit-mode');
          if (main) main.style.display = 'none';
          if (edit) edit.style.display = 'block';
          const err = document.getElementById('mms-edit-error');
          if (err) err.style.display = 'none';
        },

        closeEditMode() {
          const main = document.getElementById('mms-main-view');
          const edit = document.getElementById('mms-edit-mode');
          if (main) main.style.display = 'block';
          if (edit) edit.style.display = 'none';
        },

        saveEditMode() {
          const editor = document.getElementById('mms-yaml-editor');
          const err = document.getElementById('mms-edit-error');
          if (!editor) return;
          const text = editor.value;
          let parsed = null;
          try {
            parsed = jsyaml.load(text);
          } catch (e) {
            if (err) {
              err.textContent = 'YAML 错误：' + e.message;
              err.style.display = 'block';
            }
            return;
          }
          if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed) || Object.keys(parsed).length === 0) {
            if (err) {
              err.textContent = 'YAML 解析成功但顶层为空或不是对象（应以「状态栏:」作为根键）';
              err.style.display = 'block';
            }
            return;
          }
          const state = mmsNormalizeState(parsed) || parsed;
          try {
            this.writeState(this.floorId, state);
            const isLatest = this.checkLastAssistantFloor(this.floorId);
            if (isLatest) this.ensureInjection(state, this.floorId);
            this.closeEditMode();
            this.refreshFromVars();
            this.setIndicator('ok', '已保存手动修改');
            setTimeout(() => {
              if (!this.updating) this.setIndicator(null);
            }, 3000);
            if (this.env.hasEventApi) {
              eventEmit(MMS_EVENT_UPDATED, { message_id: this.floorId, state });
            }
          } catch (e) {
            if (err) {
              err.textContent = '保存失败：' + (e && e.message ? e.message : e);
              err.style.display = 'block';
            }
          }
        },

        // ---------- 从本楼导入（旧聊天迁移） ----------

        importFromThisFloor() {
          const legacy = extractStatusBlock(this.messageText);
          if (!legacy) {
            alert('本楼消息中没有 <Status_block> 文本，无法导入');
            return;
          }
          let parsed = null;
          try {
            parsed = jsyaml.load(legacy);
          } catch (e) {
            alert('本楼 Status_block YAML 解析失败：' + e.message);
            return;
          }
          if (!parsed || Object.keys(parsed).length === 0) {
            alert('本楼 Status_block 解析成功但数据为空');
            return;
          }
          const state = mmsNormalizeState(parsed) || parsed;
          try {
            this.writeState(this.floorId, state);
            this.renderFromState(state);
            const isLatest = this.checkLastAssistantFloor(this.floorId);
            if (isLatest) this.ensureInjection(state, this.floorId);
            this.setIndicator('ok', '已从本楼导入');
            setTimeout(() => {
              if (!this.updating) this.setIndicator(null);
            }, 3000);
            if (this.env.hasEventApi) {
              eventEmit(MMS_EVENT_UPDATED, { message_id: this.floorId, state });
            }
          } catch (e) {
            alert('写入失败：' + (e && e.message ? e.message : e));
          }
        },

        // ---------- UI ----------

        initUI() {
          const cfg = this.loadConfig();

          const editBtn = document.getElementById('mms-edit-btn');
          if (editBtn) {
            editBtn.style.display = this.env.hasMessageApi ? '' : 'none';
            editBtn.addEventListener('click', () => this.openEditMode());
          }
          const editCancel = document.getElementById('mms-edit-cancel');
          if (editCancel) editCancel.addEventListener('click', () => this.closeEditMode());
          const editSave = document.getElementById('mms-edit-save');
          if (editSave) editSave.addEventListener('click', () => this.saveEditMode());

          const indicator = document.getElementById('mms-update-indicator');
          if (indicator) {
            indicator.addEventListener('click', () => {
              if (indicator.classList.contains('error')) {
                this.runUpdate(this.floorId, { manual: true });
              }
            });
          }

          const autoChk = document.getElementById('mms-auto-update');
          if (autoChk) {
            autoChk.checked = !!cfg.autoUpdate;
            autoChk.addEventListener('change', () => {
              const c = this.loadConfig();
              c.autoUpdate = autoChk.checked;
              this.saveConfig(c);
            });
          }
          const manualBtn = document.getElementById('mms-manual-update');
          if (manualBtn) manualBtn.addEventListener('click', () => this.runUpdate(this.floorId, { manual: true }));
          const importBtn = document.getElementById('mms-import-btn');
          if (importBtn) importBtn.addEventListener('click', () => this.importFromThisFloor());

          const bindField = (id, key, transform) => {
            const el = document.getElementById(id);
            if (!el) return;
            if (cfg[key] != null && cfg[key] !== '') el.value = cfg[key];
            const handler = () => {
              const c = this.loadConfig();
              c[key] = transform ? transform(el.value) : el.value;
              this.saveConfig(c);
            };
            el.addEventListener('change', handler);
          };
          // ==================== 预设系统（API + 提示词下拉栏） ====================
          this.initApiPresetUI();
          this.initPromptPresetUI();

          // ---------- Debug 模式 ----------
          const debugChk = document.getElementById('mms-debug-toggle');
          const debugPanel = document.getElementById('mms-debug-panel');
          if (debugChk) {
            debugChk.checked = !!cfg.debug;
            const syncDebugPanel = () => {
              if (debugPanel) debugPanel.style.display = debugChk.checked ? 'block' : 'none';
              if (debugChk.checked) this.renderDebugPanel(this.loadDebugEntry());
            };
            debugChk.addEventListener('change', () => {
              const c = this.loadConfig();
              c.debug = debugChk.checked;
              this.saveConfig(c);
              syncDebugPanel();
            });
            syncDebugPanel();
          }
          const debugCopy = document.getElementById('mms-debug-copy');
          if (debugCopy) {
            debugCopy.addEventListener('click', () => {
              const entry = this.loadDebugEntry();
              if (!entry) return;
              const text =
                '=== [system] ===\n' +
                entry.sysPrompt +
                '\n\n=== [user] ===\n' +
                entry.userPrompt +
                '\n\n=== LLM返回 ===\n' +
                entry.response;
              try {
                navigator.clipboard.writeText(text).then(
                  () => {
                    debugCopy.textContent = '已复制';
                    setTimeout(() => (debugCopy.textContent = '复制'), 1500);
                  },
                  () => alert('复制失败，请手动选择文本'),
                );
              } catch (e) {
                alert('复制失败：' + e.message);
              }
            });
          }
          const debugClear = document.getElementById('mms-debug-clear');
          if (debugClear) {
            debugClear.addEventListener('click', () => {
              const content = document.getElementById('mms-debug-content');
              if (content) content.innerHTML = '<div class="text-gray-500 text-xs">暂无记录</div>';
              if (this.floorId != null && this.env.hasVarsApi) {
                try {
                  insertOrAssignVariables({ $mms_debug: null }, { type: 'message', message_id: this.floorId });
                } catch (e) { /* 忽略 */ }
              }
            });
          }

          // ---------- LLM 协助弹窗（读写当前提示词预设内容） ----------
          const helpBtn = document.getElementById('mms-llm-help-btn');
          const helpModal = document.getElementById('mms-llm-help-modal');
          const helpClose = document.getElementById('mms-llm-help-close');
          const helpCurrent = document.getElementById('mms-llm-help-current');
          if (helpBtn && helpModal) {
            helpBtn.addEventListener('click', () => {
              const coreTa = document.getElementById('mms-core-prompt');
              if (helpCurrent && coreTa) helpCurrent.value = coreTa.value;
              helpModal.style.display = 'flex';
              document.body.style.overflow = 'hidden';
            });
          }
          const closeHelp = () => {
            if (helpModal) helpModal.style.display = 'none';
            document.body.style.overflow = '';
          };
          if (helpClose) helpClose.addEventListener('click', closeHelp);
          if (helpModal) {
            helpModal.addEventListener('click', (e) => {
              if (e.target === helpModal) closeHelp();
            });
          }
          const helpSend = document.getElementById('mms-llm-help-send');
          if (helpSend) helpSend.addEventListener('click', () => this.llmHelpGenerate());
          const helpApply = document.getElementById('mms-llm-help-apply');
          if (helpApply && helpCurrent) {
            helpApply.addEventListener('click', () => {
              const ps = this.loadPromptPresets();
              const preset = ps.presets.find((p) => p.id === ps.active);
              const text = helpCurrent.value.trim();
              if (preset && preset.locked) {
                alert('默认预设只读。请新建一个提示词预设后再应用 LLM 协助结果');
                return;
              }
              if (preset && text) {
                preset.content = text;
                this.savePromptPresets(ps);
                this.renderPromptPresetUI();
              }
              closeHelp();
            });
          }

          this.initRosterUI();
        },

        // ---------- API 预设 UI ----------

        initApiPresetUI() {
          this.renderApiPresetUI();
          const select = document.getElementById('mms-api-preset-select');
          if (select) {
            select.addEventListener('change', () => {
              const data = this.loadApiPresets();
              data.active = select.value;
              this.saveApiPresets(data);
              // 同步当前预设配置到 $mms_config（向后兼容 runUpdate 读取）
              this.syncActiveApiToConfig(data);
              this.renderApiPresetUI();
            });
          }
          const addBtn = document.getElementById('mms-api-add');
          if (addBtn) addBtn.addEventListener('click', () => this.addApiPreset());
          const delBtn = document.getElementById('mms-api-delete');
          if (delBtn) delBtn.addEventListener('click', () => this.deleteApiPreset());
          const renameBtn = document.getElementById('mms-api-rename');
          if (renameBtn) renameBtn.addEventListener('click', () => this.renameApiPreset());
          const importBtn = document.getElementById('mms-api-import');
          if (importBtn)
            importBtn.addEventListener('click', () =>
              this.importPresetFile('.json', (data) => this.importApiPresetFile(data)),
            );
          const exportBtn = document.getElementById('mms-api-export');
          if (exportBtn) exportBtn.addEventListener('click', () => this.exportApiPresetFile());

          // 配置字段编辑（写入当前预设 + 兼容同步到 $mms_config）
          const bindApiField = (id, key, transform) => {
            const el = document.getElementById(id);
            if (!el) return;
            const handler = () => {
              const data = this.loadApiPresets();
              const preset = data.presets.find((p) => p.id === data.active);
              if (!preset) return;
              preset.config[key] = transform ? transform(el.value) : el.value;
              this.saveApiPresets(data);
              this.syncActiveApiToConfig(data);
            };
            el.addEventListener('change', handler);
          };
          bindApiField('mms-api-url', 'apiUrl');
          bindApiField('mms-api-key', 'apiKey');
          bindApiField('mms-api-model', 'model');
          bindApiField('mms-api-preset', 'preset');
          bindApiField('mms-context-floors', 'contextFloors', (v) =>
            Math.min(10, Math.max(1, parseInt(v, 10) || 2)),
          );
          const sourceSel = document.getElementById('mms-api-source');
          if (sourceSel) {
            sourceSel.addEventListener('change', () => {
              const data = this.loadApiPresets();
              const preset = data.presets.find((p) => p.id === data.active);
              if (!preset) return;
              preset.config.source = sourceSel.value;
              this.saveApiPresets(data);
              this.syncActiveApiToConfig(data);
            });
          }
        },

        renderApiPresetUI() {
          const select = document.getElementById('mms-api-preset-select');
          if (!select) return;
          const data = this.loadApiPresets();
          select.innerHTML = '';
          data.presets.forEach((p) => {
            const opt = document.createElement('option');
            opt.value = p.id;
            opt.textContent = p.name + (p.locked ? ' 🔒' : '');
            select.appendChild(opt);
          });
          select.value = data.active;
          // 表单回填当前预设
          const preset = data.presets.find((p) => p.id === data.active) || data.presets[0];
          const c = (preset && preset.config) || {};
          const set = (id, v) => {
            const el = document.getElementById(id);
            if (el) el.value = v == null ? '' : String(v);
          };
          set('mms-api-url', c.apiUrl);
          set('mms-api-key', c.apiKey);
          set('mms-api-model', c.model);
          set('mms-api-preset', c.preset);
          set('mms-context-floors', c.contextFloors != null ? c.contextFloors : 2);
          const sourceSel = document.getElementById('mms-api-source');
          if (sourceSel) sourceSel.value = c.source || 'custom';
          const delBtn = document.getElementById('mms-api-delete');
          if (delBtn) delBtn.disabled = !!(preset && preset.locked);
        },

        syncActiveApiToConfig(data) {
          const preset = data.presets.find((p) => p.id === data.active) || data.presets[0];
          if (!preset) return;
          const c = this.loadConfig();
          Object.assign(c, preset.config || {});
          this.saveConfig(c);
        },

        addApiPreset() {
          const data = this.loadApiPresets();
          const name = prompt('新 API 预设名称：', '');
          if (!name) return;
          const id = 'api_' + Date.now();
          const cur = data.presets.find((p) => p.id === data.active);
          data.presets.push({
            id,
            name,
            config: cur && !cur.locked ? JSON.parse(JSON.stringify(cur.config || {})) : {},
            locked: false,
          });
          data.active = id;
          this.saveApiPresets(data);
          this.syncActiveApiToConfig(data);
          this.renderApiPresetUI();
        },

        deleteApiPreset() {
          const data = this.loadApiPresets();
          const preset = data.presets.find((p) => p.id === data.active);
          if (!preset) return;
          if (preset.locked) {
            alert('默认预设不可删除');
            return;
          }
          if (!confirm('确定删除 API 预设「' + preset.name + '」？')) return;
          data.presets = data.presets.filter((p) => p.id !== data.active);
          data.active = 'default';
          this.saveApiPresets(data);
          this.syncActiveApiToConfig(data);
          this.renderApiPresetUI();
        },

        renameApiPreset() {
          const data = this.loadApiPresets();
          const preset = data.presets.find((p) => p.id === data.active);
          if (!preset) return;
          if (preset.locked) {
            alert('默认预设不可重命名');
            return;
          }
          const name = prompt('重命名 API 预设：', preset.name);
          if (!name) return;
          preset.name = name;
          this.saveApiPresets(data);
          this.renderApiPresetUI();
        },

        exportApiPresetFile() {
          const data = this.loadApiPresets();
          const preset = data.presets.find((p) => p.id === data.active);
          if (!preset) return;
          this.exportPresetFile(
            { type: 'mms-api-config', v: 2, name: preset.name, config: preset.config },
            'mms-api-preset.json',
          );
        },

        importApiPresetFile(data) {
          if (!data || data.type !== 'mms-api-config') {
            alert('这不是 API 预设文件（type 应为 mms-api-config）');
            return;
          }
          const ps = this.loadApiPresets();
          // 兼容 v1（扁平字段）与 v2（嵌套 config）
          const config = data.config || {
            source: data.source,
            apiUrl: data.apiUrl,
            apiKey: data.apiKey,
            model: data.model,
            preset: data.preset,
            contextFloors: data.contextFloors,
          };
          ps.presets.push({
            id: 'api_' + Date.now(),
            name: data.name || '导入的API预设',
            config,
            locked: false,
          });
          ps.active = ps.presets[ps.presets.length - 1].id;
          this.saveApiPresets(ps);
          this.syncActiveApiToConfig(ps);
          this.renderApiPresetUI();
        },

        // ---------- 提示词预设 UI ----------

        initPromptPresetUI() {
          this.renderPromptPresetUI();
          const select = document.getElementById('mms-prompt-preset-select');
          if (select) {
            select.addEventListener('change', () => {
              const data = this.loadPromptPresets();
              data.active = select.value;
              this.savePromptPresets(data);
              this.renderPromptPresetUI();
            });
          }
          const addBtn = document.getElementById('mms-prompt-add');
          if (addBtn) addBtn.addEventListener('click', () => this.addPromptPreset());
          const delBtn = document.getElementById('mms-prompt-delete');
          if (delBtn) delBtn.addEventListener('click', () => this.deletePromptPreset());
          const renameBtn = document.getElementById('mms-prompt-rename');
          if (renameBtn) renameBtn.addEventListener('click', () => this.renamePromptPreset());
          const importBtn = document.getElementById('mms-prompt-import');
          if (importBtn)
            importBtn.addEventListener('click', () =>
              this.importPresetFile('.json', (data) => this.importPromptPresetFile(data)),
            );
          const exportBtn = document.getElementById('mms-prompt-export');
          if (exportBtn) exportBtn.addEventListener('click', () => this.exportPromptPresetFile());

          // 提示词编辑器：默认预设只读，用户预设双击解锁
          const coreTa = document.getElementById('mms-core-prompt');
          if (coreTa) {
            coreTa.addEventListener('dblclick', () => {
              const data = this.loadPromptPresets();
              const preset = data.presets.find((p) => p.id === data.active);
              if (!preset || preset.locked) {
                alert('默认预设只读（随名册/地图设置动态生成）。请新建提示词预设后编辑');
                return;
              }
              coreTa.removeAttribute('readonly');
              coreTa.classList.remove('mms-core-prompt-readonly');
              coreTa.classList.add('unlocked');
              coreTa.title = '编辑中：失焦保存';
              coreTa.focus();
            });
            coreTa.addEventListener('blur', () => {
              const data = this.loadPromptPresets();
              const preset = data.presets.find((p) => p.id === data.active);
              coreTa.setAttribute('readonly', 'readonly');
              coreTa.classList.add('mms-core-prompt-readonly');
              coreTa.classList.remove('unlocked');
              coreTa.title = '双击解锁编辑';
              if (preset && !preset.locked) {
                preset.content = coreTa.value;
                this.savePromptPresets(data);
              }
            });
          }
        },

        renderPromptPresetUI() {
          const select = document.getElementById('mms-prompt-preset-select');
          const coreTa = document.getElementById('mms-core-prompt');
          if (!select) return;
          const data = this.loadPromptPresets();
          select.innerHTML = '';
          data.presets.forEach((p) => {
            const opt = document.createElement('option');
            opt.value = p.id;
            opt.textContent = p.name + (p.locked ? ' 🔒' : '');
            select.appendChild(opt);
          });
          select.value = data.active;
          const preset = data.presets.find((p) => p.id === data.active) || data.presets[0];
          if (coreTa) {
            if (preset && preset.locked) {
              coreTa.value = mmsBuildSystemPrompt(this.loadRoster());
            } else if (preset) {
              coreTa.value = preset.content || '';
            }
          }
          const label = document.getElementById('mms-core-prompt-label');
          if (label) {
            label.innerHTML = preset && preset.locked
              ? '提示词全文（默认协议 · 只读，随名册/据点/地图设置<b>动态生成</b>）'
              : '提示词全文（自定义预设 · <b>双击解锁编辑</b>，失焦保存）';
          }
          const hint = document.getElementById('mms-core-prompt-hint');
          if (hint) {
            hint.textContent = preset && preset.locked
              ? '默认协议按当前设置实时拼装；新建预设的初始值为当前默认协议快照，可自由修改（自定义卡片格式直接写进去）'
              : '此预设内容固定存储，不再随设置变化；LLM 协助的结果会写入当前预设';
          }
          const delBtn = document.getElementById('mms-prompt-delete');
          if (delBtn) delBtn.disabled = !!(preset && preset.locked);
        },

        // 供名册/地图/据点设置变化时刷新默认预设显示
        refreshCorePromptDisplay() {
          const data = this.loadPromptPresets();
          const preset = data.presets.find((p) => p.id === data.active);
          if (preset && preset.locked) this.renderPromptPresetUI();
        },

        addPromptPreset() {
          const data = this.loadPromptPresets();
          const name = prompt('新提示词预设名称：', '');
          if (!name) return;
          const id = 'prompt_' + Date.now();
          // 初始值 = 当前默认协议快照
          data.presets.push({
            id,
            name,
            content: mmsBuildSystemPrompt(this.loadRoster()),
            locked: false,
          });
          data.active = id;
          this.savePromptPresets(data);
          this.renderPromptPresetUI();
        },

        deletePromptPreset() {
          const data = this.loadPromptPresets();
          const preset = data.presets.find((p) => p.id === data.active);
          if (!preset) return;
          if (preset.locked) {
            alert('默认预设不可删除');
            return;
          }
          if (!confirm('确定删除提示词预设「' + preset.name + '」？')) return;
          data.presets = data.presets.filter((p) => p.id !== data.active);
          data.active = 'default';
          this.savePromptPresets(data);
          this.renderPromptPresetUI();
        },

        renamePromptPreset() {
          const data = this.loadPromptPresets();
          const preset = data.presets.find((p) => p.id === data.active);
          if (!preset) return;
          if (preset.locked) {
            alert('默认预设不可重命名');
            return;
          }
          const name = prompt('重命名提示词预设：', preset.name);
          if (!name) return;
          preset.name = name;
          this.savePromptPresets(data);
          this.renderPromptPresetUI();
        },

        exportPromptPresetFile() {
          const data = this.loadPromptPresets();
          const preset = data.presets.find((p) => p.id === data.active);
          if (!preset) return;
          this.exportPresetFile(
            { type: 'mms-prompt-config', v: 2, name: preset.name, content: preset.locked ? '' : preset.content },
            'mms-prompt-preset.json',
          );
        },

        importPromptPresetFile(data) {
          if (!data || data.type !== 'mms-prompt-config') {
            alert('这不是提示词预设文件（type 应为 mms-prompt-config）');
            return;
          }
          const ps = this.loadPromptPresets();
          // 兼容 v1（corePrompt+customPrompt）与 v2（content）
          let content = data.content;
          if (content == null) {
            const parts = [];
            if (data.corePrompt) parts.push(data.corePrompt);
            if (data.customPrompt) parts.push(data.customPrompt);
            content = parts.join('\n\n');
          }
          ps.presets.push({
            id: 'prompt_' + Date.now(),
            name: data.name || '导入的提示词',
            content: content || '',
            locked: false,
          });
          ps.active = ps.presets[ps.presets.length - 1].id;
          this.savePromptPresets(ps);
          this.renderPromptPresetUI();
        },

        // ---------- 固定角色名册 UI ----------

        // ---------- 固定角色名册 UI（方案二：抽屉表单 + 头像卡片列表） ----------

        initRosterUI() {
          if (!this.env.hasVarsApi) return;

          // 内置图片名称下拉 + 名册头像覆盖
          this.fillImageDatalists();
          this.applyRosterAvatars(this.loadRoster());
          this.renderRosterList();

          const newBtn = document.getElementById('mms-roster-new');
          const form = document.getElementById('mms-roster-form');
          if (newBtn && form) {
            newBtn.addEventListener('click', () => {
              if (form.style.display === 'block') {
                form.style.display = 'none';
              } else {
                this.openRosterForm(null);
              }
            });
            form.style.display = 'none';
          }
          const cancelBtn = document.getElementById('mms-roster-cancel');
          if (cancelBtn && form) cancelBtn.addEventListener('click', () => (form.style.display = 'none'));

          const addBtn = document.getElementById('mms-roster-add');
          if (addBtn) addBtn.addEventListener('click', () => this.addRosterCharacter());

          const attrAdd = document.getElementById('mms-attr-add-row');
          if (attrAdd) attrAdd.addEventListener('click', () => this.appendAttrRow());
          const freeAdd = document.getElementById('mms-free-add-row');
          if (freeAdd) freeAdd.addEventListener('click', () => this.appendFreeRow());

          const bindRosterText = (id, key, fallback) => {
            const el = document.getElementById(id);
            if (!el) return;
            const r = this.loadRoster();
            el.value = r[key] || fallback || '';
            el.addEventListener('change', () => {
              const rr = this.loadRoster();
              rr[key] = el.value.trim() || fallback || '';
              this.saveRoster(rr);
            });
          };
          bindRosterText('mms-absent-text', 'absentText', '本轮未提及');
          bindRosterText('mms-present-text', 'presentText', '在场·本轮未详');
          // 缺席阈值（0=每次漏输出立即显示占位文案）
          const thresholdEl = document.getElementById('mms-absent-threshold');
          if (thresholdEl) {
            thresholdEl.value = String(this.loadRoster().absentThreshold);
            thresholdEl.addEventListener('change', () => {
              const rr = this.loadRoster();
              const t = parseInt(thresholdEl.value, 10);
              rr.absentThreshold = isNaN(t) ? 3 : Math.max(0, Math.min(20, t));
              thresholdEl.value = String(rr.absentThreshold);
              this.saveRoster(rr);
            });
          }

          // 配置导入/导出（提示词与API预设独立）
          const expPrompt = document.getElementById('mms-export-prompt');
          if (expPrompt) expPrompt.addEventListener('click', () => this.exportPromptConfig());
          const expApi = document.getElementById('mms-export-api');
          if (expApi) expApi.addEventListener('click', () => this.exportApiConfig());
          const impPrompt = document.getElementById('mms-import-prompt');
          if (impPrompt) impPrompt.addEventListener('click', () => this.importPromptConfig());
          const impApi = document.getElementById('mms-import-api');
          if (impApi) impApi.addEventListener('click', () => this.importApiConfig());

          this.initBaseAndMapsUI();
          this.initMapTagsUI();
        },

        // ---------- 据点固定模块 + 地图开关 UI ----------

        initBaseAndMapsUI() {
          // 角色显示模式（全显/固定）
          const modeFull = document.getElementById('mms-char-mode-full');
          const modeFixed = document.getElementById('mms-char-mode-fixed');
          const modeDesc = document.getElementById('mms-char-mode-desc');
          const syncModeUI = () => {
            const mode = this.loadRoster().charDisplayMode || 'full';
            if (modeFull) {
              modeFull.className =
                'px-2.5 py-1 text-[11px] font-medium rounded-md ' +
                (mode === 'full' ? 'bg-primary text-white shadow-sm' : 'text-gray-400');
            }
            if (modeFixed) {
              modeFixed.className =
                'px-2.5 py-1 text-[11px] font-medium rounded-md ' +
                (mode === 'fixed' ? 'bg-primary text-white shadow-sm' : 'text-gray-400');
            }
            if (modeDesc) {
              modeDesc.textContent =
                mode === 'fixed'
                  ? '固定模式：角色列表只显示固定名册角色，新角色入人物缩略'
                  : '全显模式：固定角色 + 新登场关键NPC完整卡片';
            }
          };
          const setMode = (mode) => {
            const rr = this.loadRoster();
            rr.charDisplayMode = mode;
            this.saveRoster(rr);
            syncModeUI();
            if (this.refreshCorePromptDisplay) this.refreshCorePromptDisplay();
          };
          if (modeFull) modeFull.addEventListener('click', () => setMode('full'));
          if (modeFixed) modeFixed.addEventListener('click', () => setMode('fixed'));
          syncModeUI();

          // 据点固定模块
          const baseChk = document.getElementById('mms-base-enabled');
          const baseForm = document.getElementById('mms-base-form');
          const syncBaseForm = () => {
            if (baseForm) baseForm.style.display = baseChk && baseChk.checked ? 'block' : 'none';
          };
          if (baseChk) {
            baseChk.addEventListener('change', () => {
              const rr = this.loadRoster();
              rr.base.enabled = baseChk.checked;
              this.saveRoster(rr);
              syncBaseForm();
              if (this.refreshCorePromptDisplay) this.refreshCorePromptDisplay();
              this.applyRosterNow();
            });
          }
          const bindBaseInput = (id, key) => {
            const el = document.getElementById(id);
            if (!el) return;
            el.addEventListener('change', () => {
              const rr = this.loadRoster();
              rr.base[key] = el.value.trim();
              this.saveRoster(rr);
              if (this.refreshCorePromptDisplay) this.refreshCorePromptDisplay();
            });
          };
          bindBaseInput('mms-base-name', 'name');
          bindBaseInput('mms-base-cash', 'cash');
          const baseAddBtn = document.getElementById('mms-base-add-row');
          if (baseAddBtn) baseAddBtn.addEventListener('click', () => this.appendBaseRow('', ''));
          this.renderBaseForm();
          syncBaseForm();

          // 地图开关
          const bindMapToggle = (id, key) => {
            const el = document.getElementById(id);
            if (!el) return;
            el.addEventListener('change', () => {
              const rr = this.loadRoster();
              rr.maps[key] = el.checked;
              this.saveRoster(rr);
              if (this.refreshCorePromptDisplay) this.refreshCorePromptDisplay();
              this.renderMapTags();
              this.applyRosterNow();
            });
          };
          const miniEl = document.getElementById('mms-map-minimap');
          if (miniEl) miniEl.checked = this.loadRoster().maps.minimap !== false;
          const bigEl = document.getElementById('mms-map-bigmap');
          if (bigEl) bigEl.checked = !!this.loadRoster().maps.bigmap;
          bindMapToggle('mms-map-minimap', 'minimap');
          bindMapToggle('mms-map-bigmap', 'bigmap');
        },

        appendBaseRow(key = '', value = '') {
          const container = document.getElementById('mms-base-rows');
          if (!container) return;
          const row = document.createElement('div');
          row.className = 'flex items-center gap-1.5 base-row';
          row.innerHTML =
            '<input type="text" class="form-input w-28 base-key" placeholder="字段名 (如 载具)" value="' +
            String(key).replace(/"/g, '&quot;') +
            '" />' +
            '<input type="text" class="form-input flex-1 base-val" placeholder="初始值 (如 [🚙][轿车])" value="' +
            String(value).replace(/"/g, '&quot;') +
            '" />' +
            '<button type="button" class="attr-row-del" title="移除此行"><i class="fa fa-trash-o"></i></button>';
          row.querySelector('.attr-row-del').addEventListener('click', () => {
            row.remove();
            this.saveBaseFromForm();
          });
          row.querySelector('.base-key').addEventListener('change', () => this.saveBaseFromForm());
          row.querySelector('.base-val').addEventListener('change', () => this.saveBaseFromForm());
          container.appendChild(row);
        },

        renderBaseForm() {
          const container = document.getElementById('mms-base-rows');
          const base = this.loadRoster().base;
          const nameEl = document.getElementById('mms-base-name');
          const cashEl = document.getElementById('mms-base-cash');
          const baseChk = document.getElementById('mms-base-enabled');
          if (baseChk) baseChk.checked = !!base.enabled;
          if (nameEl) nameEl.value = base.name || '';
          if (cashEl) cashEl.value = base.cash || '';
          if (container) {
            container.innerHTML = '';
            for (const f of base.fields || []) {
              this.appendBaseRow(f.key || '', f.value || '');
            }
          }
        },

        saveBaseFromForm() {
          const rr = this.loadRoster();
          const fields = [];
          document.querySelectorAll('#mms-base-rows .base-row').forEach((row) => {
            const key = row.querySelector('.base-key').value.trim();
            const val = row.querySelector('.base-val').value.trim();
            if (key) fields.push({ key, value: val });
          });
          rr.base.fields = fields;
          this.saveRoster(rr);
          if (this.refreshCorePromptDisplay) this.refreshCorePromptDisplay();
        },

        // ---------- 地图标签管理（三栏：池/小地图/大地图，互斥，多选迁移） ----------

        mapTagsSelection: new Set(),

        initMapTagsUI() {
          const moveMini = document.getElementById('mms-tags-move-mini');
          if (moveMini) moveMini.addEventListener('click', () => this.moveSelectedTags('mini'));
          const moveBig = document.getElementById('mms-tags-move-big');
          if (moveBig) moveBig.addEventListener('click', () => this.moveSelectedTags('big'));
          const resetMini = document.getElementById('mms-tags-reset-mini');
          if (resetMini) resetMini.addEventListener('click', () => this.resetMapTags('mini'));
          const resetBig = document.getElementById('mms-tags-reset-big');
          if (resetBig) resetBig.addEventListener('click', () => this.resetMapTags('big'));
          this.renderMapTags();
        },

        renderMapTags() {
          const cfg = this.loadRoster().mapTags;
          const tagInfo = {};
          for (const t of MMS_ALL_MAP_TAGS) tagInfo[t.name] = t;

          // mode: 'pool' = 池中芯片（多选迁移），'map' = 地图栏芯片（单击退回池）
          const makeChip = (name, mode) => {
            const info = tagInfo[name] || { type: 'svg' };
            const chip = document.createElement('span');
            chip.className = 'map-tag-chip' + (this.mapTagsSelection.has(name) ? ' selected' : '');
            chip.setAttribute('data-tag', name);
            const bgMap = typeof BACKGROUND_MAP !== 'undefined' ? BACKGROUND_MAP : null;
            if (info.type === 'image' && bgMap && bgMap[name]) {
              const img = document.createElement('img');
              img.src = bgMap[name];
              img.loading = 'lazy';
              img.alt = '';
              chip.appendChild(img);
            } else if (info.type === 'image') {
              chip.textContent = '🖼 ';
            }
            chip.appendChild(document.createTextNode(name));
            if (mode === 'pool') {
              // 池中：多选（配合迁入按钮）
              chip.addEventListener('click', () => {
                if (this.mapTagsSelection.has(name)) this.mapTagsSelection.delete(name);
                else this.mapTagsSelection.add(name);
                chip.classList.toggle('selected');
              });
            } else if (mode === 'map') {
              // 地图栏：单击直接退回池（附 title 提示）
              chip.title = '点击退回标签池';
              chip.addEventListener('click', () => {
                const rr = this.loadRoster();
                rr.mapTags.mini = rr.mapTags.mini.filter((x) => x !== name);
                rr.mapTags.big = rr.mapTags.big.filter((x) => x !== name);
                if (!rr.mapTags.pool.includes(name)) rr.mapTags.pool.push(name);
                this.saveRoster(rr);
                this.mapTagsSelection.delete(name);
                this.renderMapTags();
                if (this.refreshCorePromptDisplay) this.refreshCorePromptDisplay();
              });
            }
            return chip;
          };

          const poolEl = document.getElementById('mms-tags-pool');
          const miniEl = document.getElementById('mms-tags-mini');
          const bigEl = document.getElementById('mms-tags-big');
          if (poolEl) {
            poolEl.innerHTML = '';
            for (const n of cfg.pool) poolEl.appendChild(makeChip(n, 'pool'));
            if (!cfg.pool.length) poolEl.innerHTML = '<span class="text-[10px] text-gray-500">池空：所有标签已分配</span>';
          }
          const poolCount = document.getElementById('mms-tags-pool-count');
          if (poolCount) poolCount.textContent = cfg.pool.length + ' 个可选';
          if (miniEl) {
            miniEl.innerHTML = '';
            for (const n of cfg.mini) miniEl.appendChild(makeChip(n, 'map'));
            if (!cfg.mini.length) miniEl.innerHTML = '<span class="text-[10px] text-gray-500">未分配（AI 提示词将无小地图白名单）</span>';
          }
          if (bigEl) {
            bigEl.innerHTML = '';
            for (const n of cfg.big) bigEl.appendChild(makeChip(n, 'map'));
            if (!cfg.big.length) bigEl.innerHTML = '<span class="text-[10px] text-gray-500">未分配</span>';
          }
        },

        saveMapTags(cfg) {
          const rr = this.loadRoster();
          rr.mapTags = cfg;
          this.saveRoster(rr);
          this.mapTagsSelection.clear();
          this.renderMapTags();
          if (this.refreshCorePromptDisplay) this.refreshCorePromptDisplay();
          this.applyRosterNow();
        },

        // 池中勾选的标签迁入目标栏（从另一栏互斥移除）
        moveSelectedTags(target) {
          const cfg = this.loadRoster().mapTags;
          if (!this.mapTagsSelection.size) {
            alert('请先在标签池或地图栏中点击选择标签');
            return;
          }
          const picked = [...this.mapTagsSelection];
          const other = target === 'mini' ? 'big' : 'mini';
          for (const n of picked) {
            if (!cfg[target].includes(n)) cfg[target].push(n);
            cfg[other] = cfg[other].filter((x) => x !== n);
            cfg.pool = cfg.pool.filter((x) => x !== n);
          }
          this.saveMapTags(cfg);
        },

        // 重置目标栏：标签回池
        resetMapTags(target) {
          const cfg = this.loadRoster().mapTags;
          const moved = cfg[target];
          cfg[target] = [];
          for (const n of moved) if (!cfg.pool.includes(n)) cfg.pool.push(n);
          this.saveMapTags(cfg);
        },

        // 表单动态行：数值属性（名称 + 当前/上限）
        appendAttrRow(key = '', cur = '', max = '') {
          const container = document.getElementById('mms-attr-rows');
          if (!container) return;
          const row = document.createElement('div');
          row.className = 'flex items-center gap-1.5 attr-row';
