            '<input type="text" class="form-input flex-1 attr-key" placeholder="属性名 (如 气血/理智)" value="' +
            String(key).replace(/"/g, '&quot;') +
            '" />' +
            '<input type="text" class="form-input w-14 text-center attr-cur" placeholder="当前" value="' +
