            '" />' +
            '<span class="text-gray-400 text-xs">/</span>' +
            '<input type="text" class="form-input w-14 text-center attr-max" placeholder="上限" value="' +
            String(max).replace(/"/g, '&quot;') +
            '" />' +
            '<button type="button" class="attr-row-del" title="移除此行"><i class="fa fa-trash-o"></i></button>';
          row.querySelector('.attr-row-del').addEventListener('click', () => row.remove());
          container.appendChild(row);
        },

        // 表单动态行：自由属性键值对
        appendFreeRow(key = '', val = '') {
