        // 打开表单时填充默认行（首次或清空后）
        seedRosterForm() {
          const attrRows = document.getElementById('mms-attr-rows');
          const freeRows = document.getElementById('mms-free-rows');
          if (!attrRows || !freeRows) return;
          if (attrRows.children.length === 0) {
            this.appendAttrRow('气血', '100', '100');
          }
          if (freeRows.children.length === 0) {
            this.appendFreeRow('内心', '');
            this.appendFreeRow('穿着', '');
          }
        },

        // 名册卡片列表（头像缩略 + 数值胶囊 + 自由属性摘要 + 删除）
        renderRosterList() {
          const listEl = document.getElementById('mms-roster-list');
          if (!listEl) return;
          const roster = this.loadRoster();

          // 计数徽章（设置内 + 主视图 summary）
          const countBadge = document.getElementById('mms-roster-count');
          if (countBadge) countBadge.textContent = roster.characters.length + ' 名';
          const mainBadge = document.getElementById('mms-roster-count-main');
          if (mainBadge) {
            if (roster.characters.length) {
              mainBadge.textContent = roster.characters.length + ' 名常驻';
              mainBadge.style.display = '';
            } else {
              mainBadge.style.display = 'none';
            }
          }

          listEl.innerHTML = '';
          if (!roster.characters.length) {
            listEl.innerHTML =
              '<div class="text-xs text-gray-500 py-1">名册为空。添加后角色将常驻角色列表，且其量化属性受命令协议保护。</div>';
            return;
          }
          roster.characters.forEach((r, idx) => {
            const plain = mmsPlainName(r.name) || r.name || '?';
            const avatarInitial = String(plain).slice(0, 1);

            // 头像：立绘标签 → PORTRAIT_MAP 匹配；否则按名字匹配
            let avatarUrl = '';
            if (window.PORTRAIT_MAP && typeof window.PORTRAIT_MAP === 'object') {
              const tagM = String(r.portraitTag || '').match(/【\s*立绘\s*([^】]+)\s*】/);
              const roleKey = tagM ? tagM[1].trim() : plain;
              if (roleKey) {
                const matchedKey = Object.keys(window.PORTRAIT_MAP).find(
                  (k) => k === roleKey || roleKey.includes(k) || k.includes(roleKey),
                );
                if (matchedKey) avatarUrl = window.PORTRAIT_MAP[matchedKey];
              }
            }

            const metricChips = (r.attrs || [])
              .map((a) => {
                const v = a.value == null ? '' : String(a.value);
                return '<span class="metric-chip">' + (a.key + ': ' + v).replace(/</g, '&lt;') + '</span>';
              })
              .join(' ');

            const freeSnippet = (r.freeInitials ? Object.keys(r.freeInitials) : (r.freeFields || []))
              .slice(0, 2)
              .map((k) => {
                const v = (r.freeInitials && r.freeInitials[k]) || '';
                return (
                  '<span class="text-gray-400 mr-2">' +
                  String(k).replace(/</g, '&lt;') +
                  ': <span class="text-gray-300">' +
                  String(v || '—').replace(/</g, '&lt;').slice(0, 20) +
                  '</span></span>'
                );
              })
              .join('');

            const card = document.createElement('div');
            card.className =
              'roster-card roster-surface p-2.5 rounded-xl border border-gray-700/15 flex items-start justify-between gap-2';
            card.innerHTML =
              '<div class="flex items-start gap-2.5 min-w-0 flex-1">' +
              '<div class="w-9 h-9 rounded-lg overflow-hidden border border-gray-700/30 flex-shrink-0 bg-stone-800 flex items-center justify-center text-primary font-bold text-xs">' +
              (avatarUrl
                ? '<img src="' + avatarUrl + '" alt="' + plain.replace(/"/g, '&quot;') + '" class="w-full h-full object-cover" loading="lazy" onerror="this.outerHTML=\'<span>' + avatarInitial + '</span>\'" />'
                : '<span>' + avatarInitial + '</span>') +
              '</div>' +
              '<div class="min-w-0 flex-1">' +
              '<div class="flex items-center gap-1.5 flex-wrap">' +
              '<span class="text-xs font-bold text-gray-200">' + String(r.name || '').replace(/</g, '&lt;') + '</span>' +
              '<span class="text-[10px] text-gray-400">(' + String(r.role || '常驻角色').replace(/</g, '&lt;') + ')</span>' +
              '</div>' +
              '<div class="flex items-center gap-1 my-1 flex-wrap">' + metricChips + '</div>' +
              '<div class="text-[10px] truncate">' + freeSnippet + '</div>' +
              '</div>' +
              '</div>' +
              '<div class="flex items-center gap-1 flex-shrink-0 pt-0.5">' +
              '<button class="attr-row-del roster-edit-btn" title="编辑此角色" style="color: #9ca3af"><i class="fa fa-pencil"></i></button>' +
              '<button class="attr-row-del roster-del-btn" title="从名册移除"><i class="fa fa-trash-o"></i></button>' +
              '</div>';

            card.querySelector('.roster-edit-btn').addEventListener('click', () => {
              this.openRosterForm(idx);
            });
            card.querySelector('.roster-del-btn').addEventListener('click', () => {
              if (!confirm('确定要从常驻名册中移除「' + plain + '」吗？')) return;
              const rr = this.loadRoster();
              rr.characters.splice(idx, 1);
              this.saveRoster(rr);
              this.renderRosterList();
            });
            listEl.appendChild(card);
          });
        },

        addRosterCharacter() {
          const get = (id) => {
            const el = document.getElementById(id);
            return el ? el.value.trim() : '';
          };
          const name = get('mms-roster-name');
          if (!name) {
            alert('请填写角色姓名');
            return;
          }

          // 数值属性行：名称 + 当前/上限 → attrs [{key, value}]（value = "cur/max" 或 "cur"）
          const attrs = [];
          document.querySelectorAll('#mms-attr-rows .attr-row').forEach((row) => {
            const key = row.querySelector('.attr-key').value.trim();
            const cur = row.querySelector('.attr-cur').value.trim();
            const max = row.querySelector('.attr-max').value.trim();
            if (!key) return;
            const value = max ? cur + '/' + max : cur;
            attrs.push({ key, value });
          });

          // 自由属性行：键值对 → freeFields + freeInitials
          const freeFields = [];
          const freeInitials = {};
          document.querySelectorAll('#mms-free-rows .free-row').forEach((row) => {
            const key = row.querySelector('.free-key').value.trim();
            const val = row.querySelector('.free-val').value.trim();
            if (!key) return;
            freeFields.push(key);
            freeInitials[key] = val;
          });
          if (!freeFields.length) {
            freeFields.push('内心', '穿着');
          }

          const entry = {
            name: name,
            portraitTag: get('mms-roster-portrait'),
            avatar: get('mms-roster-avatar'),
            role: get('mms-roster-role'),
            attrs: attrs,
            freeFields: freeFields,
            freeInitials: freeInitials,
            weapons: get('mms-roster-weapons'),
            items: get('mms-roster-items'),
          };

          const roster = this.loadRoster();
          const nk = mmsNormalizeName(name);
          const isEdit = this.rosterEditIndex != null;
          if (!isEdit && roster.characters.some((c) => mmsNormalizeName(c.name) === nk)) {
            alert('名册中已存在同名角色');
            return;
          }
          if (isEdit) {
            roster.characters[this.rosterEditIndex] = entry;
          } else {
            roster.characters.push(entry);
          }
          this.saveRoster(roster);
          this.applyRosterAvatars(roster);
          this.renderRosterList();

          // 收起表单并复位为新增模式
          this.rosterEditIndex = null;
          const form = document.getElementById('mms-roster-form');
          if (form) form.style.display = 'none';

          // 立即应用到当前状态：新角色当场出现在角色列表（无需等待下次AI更新）
          this.applyRosterNow();
        },

        // 名册头像覆盖到 AVATAR_MAP（小地图按名字取头像）
        applyRosterAvatars(roster) {
          const map = this.getAvatarMap();
          if (!map) return;
          for (const r of (roster && roster.characters) || []) {
            if (!r || !r.avatar) continue;
            const url = this.resolveAvatarUrl(r.avatar);
            const plain = mmsPlainName(r.name);
            if (url && plain) map[plain] = url;
          }
        },

        // 把名册增量合并进当前楼层状态：只插入缺失的固定角色，绝不改动/删除其他角色
        applyRosterNow() {
          if (this.floorId == null || !this.env.hasVarsApi) return;
          try {
            const vars = this.readFloorVars(this.floorId);
            let state = vars && vars.stat_data ? mmsNormalizeState(vars.stat_data) : null;
            if (!state) {
              state = { 状态栏: {} };
            }
            const roster = this.loadRoster();
            const storyText = this.readFloorMaintext(this.floorId) || '';
            const merged = mmsApplyRosterToState(state, roster, storyText);
            this.writeState(this.floorId, merged);
            this.renderFromState(merged);
            if (this.checkLastAssistantFloor(this.floorId)) this.ensureInjection(merged, this.floorId);
            this.setIndicator('ok', '名册已应用');
            setTimeout(() => {
              if (!this.updating) this.setIndicator(null);
            }, 3000);
          } catch (e) {
            console.warn('[MMS] 应用名册失败:', e);
          }
        },

        // ---------- Debug 日志（发送提示词与返回结果） ----------

        debugLog(sysPrompt, userPrompt, raw, customApi) {
          try {
            const cfg = this.loadConfig();
            if (!cfg.debug) return;
            const entry = {
              ts: new Date().toLocaleString(),
              api: { url: customApi.apiurl || '当前酒馆连接', model: customApi.model || '默认' },
              sysPrompt: sysPrompt,
              userPrompt: userPrompt,
              response: String(raw || ''),
            };
            // 存入本楼变量（$前缀对AI不可见）；只保留最近一条
            if (this.floorId != null && this.env.hasVarsApi) {
              insertOrAssignVariables({ $mms_debug: entry }, { type: 'message', message_id: this.floorId });
            }
            this.renderDebugPanel(entry);
          } catch (e) {
            console.warn('[MMS] debug记录失败:', e);
          }
        },

        loadDebugEntry() {
          try {
            if (this.floorId == null || !this.env.hasVarsApi) return null;
            const vars = this.readFloorVars(this.floorId);
            return (vars && vars.$mms_debug) || null;
          } catch (e) {
            return null;
          }
        },

        renderDebugPanel(entry) {
          const content = document.getElementById('mms-debug-content');
          if (!content || !entry) return;
          const esc = (s) =>
            String(s || '')
              .replace(/&/g, '&amp;')
              .replace(/</g, '&lt;')
              .replace(/>/g, '&gt;');
          content.innerHTML =
            '<div class="text-gray-500">' + esc(entry.ts) + ' · ' + esc(entry.api.url) + ' · ' + esc(entry.api.model) + '</div>' +
            '<div><div class="font-bold text-gray-300 mb-0.5">[system] 发送的提示词</div><pre class="whitespace-pre-wrap break-all bg-black/30 rounded p-2 m-0">' + esc(entry.sysPrompt) + '</pre></div>' +
            '<div><div class="font-bold text-gray-300 mb-0.5">[user] 发送的用户消息</div><pre class="whitespace-pre-wrap break-all bg-black/30 rounded p-2 m-0">' + esc(entry.userPrompt) + '</pre></div>' +
            '<div><div class="font-bold text-emerald-400 mb-0.5">LLM 返回</div><pre class="whitespace-pre-wrap break-all bg-emerald-900/10 rounded p-2 m-0">' + esc(entry.response) + '</pre></div>';
        },

        // ---------- LLM 协助生成自定义提示词 ----------

        async llmHelpGenerate() {
          const currentEl = document.getElementById('mms-llm-help-current');
          const requestEl = document.getElementById('mms-llm-help-request');
          const sendBtn = document.getElementById('mms-llm-help-send');
          if (!requestEl || !currentEl) return;
          const request = requestEl.value.trim();
          if (!request) {
            alert('请先在右栏填写你的要求');
            return;
          }
          if (!this.env.hasGenApi) {
            alert('当前环境不支持独立生成');
            return;
          }
          if (sendBtn) {
            sendBtn.disabled = true;
            sendBtn.innerHTML = '<i class="fa fa-spinner fa-spin mr-1"></i>请求中…';
          }
          try {
            const cfg = this.loadConfig();
            const helpSys =
              '你是 SillyTavern 状态栏插件的提示词工程师。插件通过一个独立 LLM 维护跑团状态数据（JSON，顶层键「状态栏」，含日期/地点/小地图/角色列表/人物/据点/行动选项等模块）。' +
              '用户的系统提示词已包含模块结构与校验命令协议（[HP-2]式命令），自定义提示词会追加在系统提示词之后。\n' +
              '请依据用户要求，为「自定义卡片模块」编写一段提示词：说明模块名（状态栏顶层的新键）、JSON 结构（含字段与示例）、内容更新规则。' +
              '要求：输出纯文本提示词本体（可含##小节），不要解释你的思路，不要输出代码块围栏，控制在300字以内。';
            const helpUser =
              (currentEl.value.trim() ? '<当前已有的自定义提示词>\n' + currentEl.value.trim() + '\n</当前已有的自定义提示词>\n\n' : '') +
              '<我的要求>\n' + request + '\n</我的要求>\n\n请输出完善后的完整自定义提示词（整合当前已有内容与新要求）。';
            const config = {
              ordered_prompts: [
                { role: 'system', content: helpSys },
                { role: 'user', content: helpUser },
              ],
              custom_api: this.buildCustomApi(cfg),
              should_silence: true,
              generation_id: 'mms-llm-help-' + Date.now(),
            };
            const result = await generateRaw(config);
            let text = typeof result === 'string' ? result : (result && result.content) || '';
            text = text.replace(/^```[a-zA-Z]*\s*\n?/, '').replace(/\n?```\s*$/, '').trim();
            if (!text) throw new Error('AI 返回为空');
            currentEl.value = text;
            requestEl.value = '';
          } catch (e) {
            alert('LLM 协助失败：' + (e && e.message ? e.message : e));
          } finally {
            if (sendBtn) {
              sendBtn.disabled = false;
              sendBtn.innerHTML = '<i class="fa fa-paper-plane mr-1"></i>发送请求';
            }
          }
        },

        // ---------- 配置导入 / 导出（提示词与API预设独立） ----------

        ioFill(text, okMsg) {
          const ta = document.getElementById('mms-io-text');
          if (ta) ta.value = text;
          try {
            navigator.clipboard.writeText(text).catch(() => {});
          } catch (e) { /* 剪贴板不可用则只填入文本框 */ }
          this.setIndicator('ok', okMsg);
          setTimeout(() => {
            if (!this.updating) this.setIndicator(null);
          }, 2500);
        },

        exportPromptConfig() {
          const cfg = this.loadConfig();
          const payload = {
            type: 'mms-prompt-config',
            v: 1,
            corePrompt: cfg.corePrompt || '',
            customPrompt: cfg.systemPrompt || '',
          };
          this.ioFill(JSON.stringify(payload, null, 2), '提示词已导出并复制');
        },

        exportApiConfig() {
          const cfg = this.loadConfig();
          const payload = {
            type: 'mms-api-config',
            v: 1,
            source: cfg.source,
            apiUrl: cfg.apiUrl,
            apiKey: cfg.apiKey,
            model: cfg.model,
            preset: cfg.preset,
            contextFloors: cfg.contextFloors,
          };
          this.ioFill(JSON.stringify(payload, null, 2), 'API 预设已导出并复制');
        },

        ioParse() {
          const ta = document.getElementById('mms-io-text');
          if (!ta || !ta.value.trim()) {
            alert('请先把导出的 JSON 粘贴到文本框');
            return null;
          }
          try {
            return JSON.parse(ta.value.trim());
          } catch (e) {
            alert('JSON 解析失败：' + e.message);
            return null;
          }
        },

        importPromptConfig() {
          const data = this.ioParse();
          if (!data) return;
          if (data.type !== 'mms-prompt-config') {
            alert('这不是提示词配置（type 应为 mms-prompt-config）');
            return;
          }
          const c = this.loadConfig();
          if (data.corePrompt && String(data.corePrompt).trim()) c.corePrompt = String(data.corePrompt);
          else delete c.corePrompt;
          if (data.customPrompt && String(data.customPrompt).trim()) c.systemPrompt = String(data.customPrompt);
          else delete c.systemPrompt;
          this.saveConfig(c);
          // 刷新UI
          const coreTa = document.getElementById('mms-core-prompt');
          if (coreTa) coreTa.value = c.corePrompt || mmsBuildSystemPrompt(this.loadRoster());
          const customTa = document.getElementById('mms-custom-prompt');
          if (customTa) customTa.value = c.systemPrompt || '';
          this.setIndicator('ok', '提示词已导入');
          setTimeout(() => {
            if (!this.updating) this.setIndicator(null);
          }, 2500);
        },

        importApiConfig() {
          const data = this.ioParse();
          if (!data) return;
          if (data.type !== 'mms-api-config') {
            alert('这不是 API 预设（type 应为 mms-api-config）');
            return;
          }
          const c = this.loadConfig();
          const fields = ['source', 'apiUrl', 'apiKey', 'model', 'preset'];
          for (const f of fields) {
            if (data[f] != null && data[f] !== '') c[f] = data[f];
          }
          if (data.contextFloors != null) c.contextFloors = data.contextFloors;
          this.saveConfig(c);
          // 刷新UI
          const bind = { 'mms-api-url': 'apiUrl', 'mms-api-key': 'apiKey', 'mms-api-model': 'model', 'mms-api-preset': 'preset', 'mms-context-floors': 'contextFloors' };
          for (const [id, key] of Object.entries(bind)) {
            const el = document.getElementById(id);
            if (el && c[key] != null) el.value = c[key];
          }
          const sourceSel = document.getElementById('mms-api-source');
          if (sourceSel && c.source) sourceSel.value = c.source;
          this.setIndicator('ok', 'API 预设已导入');
          setTimeout(() => {
            if (!this.updating) this.setIndicator(null);
          }, 2500);
        },

        // ---------- 名册编辑 ----------

        // 表单当前编辑的名册索引（null=新增模式）
        rosterEditIndex: null,

        openRosterForm(idx) {
          const form = document.getElementById('mms-roster-form');
          const titleEl = document.getElementById('mms-roster-form-title');
          const iconEl = document.getElementById('mms-roster-form-icon');
          if (!form) return;
          this.rosterEditIndex = idx == null ? null : idx;
          // 清空动态行
          const attrRows = document.getElementById('mms-attr-rows');
          if (attrRows) attrRows.innerHTML = '';
          const freeRows = document.getElementById('mms-free-rows');
          if (freeRows) freeRows.innerHTML = '';

          if (idx == null) {
            if (titleEl) titleEl.textContent = '添加新角色至常驻名册';
            if (iconEl) iconEl.className = 'fa fa-user-plus';
            for (const id of ['mms-roster-name', 'mms-roster-portrait', 'mms-roster-avatar', 'mms-roster-role', 'mms-roster-weapons', 'mms-roster-items']) {
              const el = document.getElementById(id);
              if (el) el.value = '';
            }
            this.seedRosterForm();
          } else {
            const roster = this.loadRoster();
            const r = roster.characters[idx];
            if (!r) return;
            if (titleEl) titleEl.textContent = '编辑常驻角色：' + (mmsPlainName(r.name) || r.name);
            if (iconEl) iconEl.className = 'fa fa-pencil';
            const set = (id, v) => {
              const el = document.getElementById(id);
              if (el) el.value = v == null ? '' : String(v);
            };
            set('mms-roster-name', r.name);
            set('mms-roster-portrait', r.portraitTag);
            set('mms-roster-avatar', r.avatar);
            set('mms-roster-role', r.role);
            set('mms-roster-weapons', r.weapons);
            set('mms-roster-items', r.items);
            for (const a of r.attrs || []) {
              const m = String(a.value || '').match(/^(-?\d+(?:\.\d+)?)\s*\/\s*(-?\d+(?:\.\d+)?)$/);
              this.appendAttrRow(a.key || '', m ? m[1] : a.value || '', m ? m[2] : '');
            }
            const freeFields = r.freeFields && r.freeFields.length ? r.freeFields : ['内心', '穿着'];
            for (const f of freeFields) {
              this.appendFreeRow(f, (r.freeInitials && r.freeInitials[f]) || '');
            }
          }
          form.style.display = 'block';
          form.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        },

        // 头像URL解析：名称→AVATAR_MAP、URL直用
        resolveAvatarUrl(input) {
          const s = String(input || '').trim();
          if (!s) return '';
          if (/^https?:\/\//i.test(s)) return s;
          const map = this.getAvatarMap();
          if (map) {
            const matchedKey = Object.keys(map).find(
              (k) => k === s || s.includes(k) || k.includes(s),
            );
            if (matchedKey) return map[matchedKey];
          }
          return '';
        },

        // AVATAR_MAP/PORTRAIT_MAP 是主脚本的 const（词法作用域），此处同作用域直接引用
        getAvatarMap() {
          try {
            return typeof AVATAR_MAP !== 'undefined' ? AVATAR_MAP : null;
          } catch (e) {
            return null;
          }
        },

        // 填充内置图片名称下拉（datalist）
        fillImageDatalists() {
          const portraitList = document.getElementById('mms-portrait-list');
          const avatarList = document.getElementById('mms-avatar-list');
          const portraitMap = typeof PORTRAIT_MAP !== 'undefined' ? PORTRAIT_MAP : window.PORTRAIT_MAP;
          const avatarMap = this.getAvatarMap();
          const fill = (dl, map) => {
            if (!dl || !map || typeof map !== 'object') return;
            dl.innerHTML = '';
            Object.keys(map).forEach((k) => {
              const opt = document.createElement('option');
              opt.value = k;
              dl.appendChild(opt);
            });
          };
          fill(portraitList, portraitMap);
          fill(avatarList, avatarMap);
        },

        // ---------- 启动 ----------

        async boot() {
          this.detectEnv();
          this.initUI();

          if (!this.env.hasMessageApi) {
            const t = document.getElementById('time-display');
            const l = document.getElementById('location-display');
            if (t) t.textContent = '⏳ 独立预览模式';
            if (l) l.textContent = '📍 请通过酒馆助手正则注入使用';
            return;
          }

          let floorId = null;
          try {
            floorId = getCurrentMessageId();
          } catch (e) {
            floorId = null;
          }
          if (floorId == null) return;
          this.floorId = floorId;

          let msg = null;
          try {
            msg = getCurrentMessage();
          } catch (e) {
            msg = null;
          }
          if (!msg || typeof msg.message !== 'string') return;
          this.messageText = msg.message;

          // 正文渲染（与旧版一致）
          const maintextContent = extractMaintext(this.messageText);
          if (maintextContent) updateMaintext(maintextContent);

          // 是否最新 AI 楼层（更新、注入、兜底职责的承担者）
          this.isLastAssistantFloor = this.checkLastAssistantFloor(floorId);

          // 状态读取与渲染：变量优先（统一规范化为模块化结构），旧格式回退
          const vars = this.env.hasVarsApi ? this.readFloorVars(floorId) : null;
          const rawState = vars && vars.stat_data;
          const state = rawState ? mmsNormalizeState(rawState) || rawState : null;
          const meta = vars && vars.$mms_meta;
          const msgHash = this.hashStr(this.messageText);

          if (state) {
            this.renderFromState(state);
            if (meta && meta.hash === msgHash) {
              this.setIndicator('ok', '状态数据为最新');
              setTimeout(() => {
                if (!this.updating) this.setIndicator(null);
              }, 2000);
            } else {
              this.setIndicator('updating', '检测到楼层内容变化，正在重新更新…');
              this.maybeAutoUpdate();
            }
            if (this.isLastAssistantFloor) this.ensureInjection(state, floorId);
          } else {
            const legacyYaml = extractStatusBlock(this.messageText);
            if (legacyYaml) {
              // 旧格式楼层：解析 → 规范化 → 渲染
              let legacyState = null;
              try {
                const parsed = jsyaml.load(legacyYaml);
                legacyState = parsed ? mmsNormalizeState(parsed) : null;
              } catch (e) {
                console.warn('[MMS] 旧格式状态解析失败，按原样渲染:', e);
              }
              if (legacyState) {
                this.renderFromState(legacyState);
              } else {
                updateYamlDataSource(legacyYaml);
                setTimeout(() => reRenderStatusBar(), 100);
              }
              this.maybeAutoUpdate(); // 旧格式楼层：异步生成变量快照
            } else {
              const prev = await this.findPrevState(floorId);
              if (prev) {
                this.renderFromState(prev.state);
                this.setIndicator('updating', '状态更新中…');
              } else {
                const t = document.getElementById('time-display');
                const l = document.getElementById('location-display');
                if (t) t.textContent = '⏳ 等待状态数据';
                if (l) l.textContent = '📍 首次使用：设置 → 立即更新 或 从本楼导入';
              }
              this.maybeAutoUpdate();
            }
          }

          // 事件刷新监听（本楼原地刷新，不重载 iframe）
          if (this.env.hasEventApi) {
            try {
              eventOn(MMS_EVENT_UPDATED, (payload) => {
                if (payload && payload.message_id === this.floorId) this.refreshFromVars();
              });
              eventOn(MMS_EVENT_FAILED, (payload) => {
                if (payload && payload.message_id === this.floorId) {
                  this.setIndicator('error', '更新失败：' + payload.error + '（点击重试）');
                }
              });
            } catch (e) {
              /* 事件系统异常不影响渲染 */
            }
          }

          this.setupDriftGuard();
        },
      };

      // 暴露到 window 便于控制台调试与测试
      window.MMS = MMS;

      document.addEventListener('DOMContentLoaded', function () {
        MMS.boot();
        window.statusBlockInitialized = true;
      });
    </script>
  </body>
</html>
